const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const Store={
 p:"logosx:",
 get(k,d=null){try{const v=localStorage.getItem(this.p+k);return v===null?d:JSON.parse(v)}catch{return d}},
 set(k,v){localStorage.setItem(this.p+k,JSON.stringify(v));return v},
 push(k,v,lim=500){const a=this.get(k,[]);a.unshift(v);this.set(k,a.slice(0,lim));return v},
 del(k){localStorage.removeItem(this.p+k)},
 export(){const x={};for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k?.startsWith(this.p))x[k]=localStorage.getItem(k)}return x},
 import(x){Object.entries(x||{}).forEach(([k,v])=>{if(k.startsWith(this.p))localStorage.setItem(k,v)})}
};


/* V8.15 — padrões persistentes da Bíblia X */
(function(){
  try{
    if(localStorage.getItem("logosx:bibleXCleanReading")===null) Store.set("bibleXCleanReading",true);
    if(localStorage.getItem("logosx:bibleXZoom")===null) Store.set("bibleXZoom",100);
    if(localStorage.getItem("logosx:bibleXLastSection")===null) Store.set("bibleXLastSection","reader");
  }catch(_){}
})();
// Anti-travamento global do Studio X: recupera apenas estados temporários órfãos.
(function recoverStudioOnBoot(){
 try{
  const p=Store.get("studioProcessing",null);
  if(p&&p.status==="running"){
   const age=p.started?Date.now()-Date.parse(p.started):Infinity;
   if(!Number.isFinite(age)||age>120000){
    Store.set("studioProcessing",{status:"error",progress:0,phase:0,message:"Processamento anterior recuperado automaticamente.",started:null,finished:new Date().toISOString(),engine:"",provider:"",model:"",quality:null,error:"Sessão anterior interrompida.",generationId:""});
    if(Number(Store.get("studioStep",1))===6)Store.set("studioStep",5);
   }
  }
 }catch(e){}
})();
window.addEventListener("unhandledrejection",e=>{try{const p=Store.get("studioProcessing",null);if(p?.status==="running"&&Number(Store.get("studioStep",1))===6)Store.set("studioProcessing",Object.assign({},p,{status:"error",progress:0,phase:0,message:"Falha recuperada sem bloquear a interface.",finished:new Date().toISOString(),error:String(e.reason?.message||e.reason||"Erro assíncrono"),generationId:""}))}catch(_){} });
function logosPercentColor(v){
 v=Math.max(0,Math.min(100,Number(v)||0));
 // 0 vermelho -> 50 amarelo -> 100 verde
 const hue=Math.round(v*1.2);
 return `hsl(${hue} 92% 50%)`;
}
let mobileLoadingProgress=8;let mobileLoadingTimer=null;const mobileLoadingStartedAt=performance.now();
let __journeyAudioCtx=null;
function playApprovedHomeJourneySound(){ /* 5.4.2 — áudio do flash removido a pedido do usuário. */ return false; }

function startMobileLoading(){const el=document.getElementById('mobileLoadingBar');if(!el)return;mobileLoadingTimer=setInterval(()=>{mobileLoadingProgress=Math.min(92,mobileLoadingProgress+Math.max(1,(92-mobileLoadingProgress)*.08));el.style.width=mobileLoadingProgress+'%';},120);}
function finishMobileLoading(){
 return; /* 5.4.163 — sem FX/canvas de abertura (DNA): nada entre o clique e o app pronto. */
 if(mobileLoadingTimer){clearInterval(mobileLoadingTimer);mobileLoadingTimer=null}
 const el=document.getElementById('mobileLoadingBar');
 if(el)el.style.width='100%';
 const minVisible=120;
 const wait=Math.max(180,minVisible-(performance.now()-mobileLoadingStartedAt));
 setTimeout(()=>{
   const splash=document.getElementById('mobileLoading');
   const startHomeFx=()=>{
     const host=window.matchMedia('(max-width:760px)').matches
       ? document.querySelector('.mobile-home-piece.mobile-home-hero')
       : document.querySelector('.reference-body-wrap.desktop-reference-home');
     if(!host || host.querySelector('.dna-canvas-fx-427')) return;
     window.__logosHomeFxStartedAt=performance.now();
     playApprovedHomeJourneySound();
     window.__logosReplayHomeJourney=()=>{try{document.querySelector('.dna-canvas-fx-427')?.remove();requestAnimationFrame(startHomeFx)}catch(e){}};

     const canvas=document.createElement('canvas');
     canvas.className='dna-canvas-fx-427';
     canvas.width=1313;
     canvas.height=946;
     canvas.setAttribute('aria-hidden','true');
     host.appendChild(canvas);

     const ctx=canvas.getContext('2d');
     const css=getComputedStyle(document.documentElement);
     const parseRgb=(name,fallback)=>{
       const raw=(css.getPropertyValue(name)||'').trim();
       const parts=raw.split(',').map(v=>parseFloat(v));
       return parts.length>=3&&parts.every(Number.isFinite)?parts:fallback;
     };
     const p=parseRgb('--theme-primary-rgb',[32,225,223]);
     const s=parseRgb('--theme-secondary-rgb',[226,171,54]);
     const rgba=(rgb,a)=>`rgba(${rgb[0]},${rgb[1]},${rgb[2]},${a})`;

     const W=1313,H=946;
     const start=performance.now();
     const duration=4000; /* fluxo aprovado sincronizado em ~4 segundos */

     const bez=(a,b,c,d,t)=>{
       const u=1-t;
       return {
         x:u*u*u*a.x+3*u*u*t*b.x+3*u*t*t*c.x+t*t*t*d.x,
         y:u*u*u*a.y+3*u*u*t*b.y+3*u*t*t*c.y+t*t*t*d.y
       };
     };

     /* Trajetórias calibradas sobre o DNA REAL da arte 1313x946.
        Não desenhamos uma nova hélice: só usamos estas curvas como guia de luz. */
     const green=[
       [{x:313,y:46},{x:332,y:82},{x:365,y:118},{x:417,y:165}],
       [{x:417,y:165},{x:457,y:200},{x:430,y:240},{x:367,y:284}],
       [{x:367,y:284},{x:340,y:306},{x:348,y:339},{x:425,y:373}]
     ];
     const gold=[
       [{x:548,y:45},{x:534,y:84},{x:500,y:122},{x:446,y:166}],
       [{x:446,y:166},{x:406,y:201},{x:431,y:240},{x:496,y:282}],
       [{x:496,y:282},{x:524,y:307},{x:514,y:340},{x:430,y:373}]
     ];

     /* 5.4.2 — progresso por COMPRIMENTO DE ARCO: a luz desce e volta em
        velocidade uniforme. Antes, cada trecho de bézier contava o mesmo "t",
        fazendo o brilho acelerar nos trechos curtos e "grudar" nos longos. */
     const buildLenTable=(segs)=>{
       const lens=segs.map(seg=>{
         let L=0,px=seg[0].x,py=seg[0].y;
         for(let i=1;i<=24;i++){
           const pt=bez(seg[0],seg[1],seg[2],seg[3],i/24);
           const dx=pt.x-px,dy=pt.y-py;
           L+=Math.hypot(dx,dy);px=pt.x;py=pt.y;
         }
         return L;
       });
       const starts=[];let acc=0;
       for(let i=0;i<lens.length;i++){starts.push(acc);acc+=lens[i];}
       return {lens,starts,total:acc};
     };
     const lenFwd=new WeakMap(),lenRev=new WeakMap();
     const lenTable=(segs,reverse=false)=>{
       const m=reverse?lenRev:lenFwd;
       let t=m.get(segs);
       if(!t){t=buildLenTable(reverse?segs.slice().reverse():segs);m.set(segs,t);}
       return t;
     };
     const pointOn=(segments,t,reverse=false)=>{
       t=Math.max(0,Math.min(0.9999,t));
       const {lens,starts,total}=lenTable(segments,reverse);
       const target=t*total;
       let i=0;
       while(i<lens.length-1&&target>starts[i]+lens[i])i++;
       const lt=lens[i]?(target-starts[i])/lens[i]:0;
       const seg=reverse?segments[segments.length-1-i]:segments[i];
       return bez(seg[0],seg[1],seg[2],seg[3],Math.max(0,Math.min(1,lt)));
     };

     const glowDot=(x,y,r,rgb,a)=>{
       const g=ctx.createRadialGradient(x,y,0,x,y,r);
       g.addColorStop(0,`rgba(255,255,255,${Math.min(1,a*1.3)})`);
       g.addColorStop(.12,rgba(rgb,a));
       g.addColorStop(.42,rgba(rgb,a*.42));
       g.addColorStop(1,rgba(rgb,0));
       ctx.fillStyle=g;
       ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();
     };

     const softEllipse=(x,y,rx,ry,rgb,a)=>{
       ctx.save();
       ctx.translate(x,y);ctx.scale(rx,ry);
       const g=ctx.createRadialGradient(0,0,0,0,0,1);
       g.addColorStop(0,rgba(rgb,a));
       g.addColorStop(.38,rgba(rgb,a*.38));
       g.addColorStop(1,rgba(rgb,0));
       ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,1,0,Math.PI*2);ctx.fill();
       ctx.restore();
     };

     const drawTravel=(segments,progress,rgb,intensity)=>{
       const head=pointOn(segments,progress);
       for(let k=0;k<11;k++){
         const tt=Math.max(0,progress-k*.018);
         const q=pointOn(segments,tt);
         glowDot(q.x,q.y,18-k*.9,rgb,intensity*(1-k/13));
       }
       glowDot(head.x,head.y,34,rgb,intensity);
     };

     /* 5.4.16 — FLUXO DE ENERGIA pela faixa: aura que acende a faixa dourada
        atrás da luz (como uma rua sendo percorrida) + núcleo quente no centro
        do fio — a energia passa POR DENTRO / SOBRE o ouro, literalmente. */
     const drawRibbonTrail=(segments,progress,rgb,intensity,reverse=false,headBoost=1)=>{
       const head=pointOn(segments,progress,reverse);
       ctx.save();
       ctx.globalCompositeOperation='lighter';
       // aura do fluxo — a faixa acende atrás da ponta, em decaimento suave
       for(let k=0;k<18;k++){
         const tt=Math.max(0,progress-k*.015);
         const q=pointOn(segments,tt,reverse);
         const f=1-k/18;
         glowDot(q.x,q.y,15-k*.45,rgb,intensity*f*f);
       }
       // núcleo do fluxo — traço intenso no centro do fio
       for(let k=0;k<9;k++){
         const tt=Math.max(0,progress-k*.022);
         const q=pointOn(segments,tt,reverse);
         glowDot(q.x,q.y,7-k*.3,rgb,intensity*.95*(1-k/11));
       }
       // ponta brilhante do fluxo
       glowDot(head.x,head.y,26,rgb,intensity);
       glowDot(head.x,head.y,48,rgb,intensity*.30*headBoost);
       ctx.restore();
     };

     /* 5.4.13 — ponto sobre a FACE DE BAIXO da fita: desvio perpendicular
        constante e suave (sem tremor). A luz DESCE POR BAIXO refazendo o
        percurso, como pedido (equilibrista por baixo do fio). */
     const underPoint=(segments,tt,reverse)=>{
       const base=pointOn(segments,tt,reverse);
       const a=pointOn(segments,Math.max(.0005,tt-.006),reverse);
       const b=pointOn(segments,Math.min(.9994,tt+.006),reverse);
       const dx=b.x-a.x,dy=b.y-a.y,L=Math.hypot(dx,dy)||1;
       let px=-dy/L,py=dx/L;
       // 5.4.14 — lado SEMPRE por baixo da fita (y crescente na tela):
       // o perpendicular (px,py) depende do sentido do trajeto; quando apontaria
       // para CIMA, inverte-se o sinal. Assim, ida (acima) e volta (abaixo)
       // mantêm o lado correto em todo o percurso.
       if(py<0){px=-px;py=-py;}
       return {x:base.x+px*9,y:base.y+py*9};
     };
     const drawUnderTrail=(segments,progress,rgb,intensity,reverse=false,headBoost=1)=>{
       const u=Math.max(0,Math.min(.9999,progress));
       const head=underPoint(segments,u,reverse);
       ctx.save();
       ctx.globalCompositeOperation='lighter';
       for(let k=0;k<15;k++){
         const tt=Math.max(0,u-k*.016);
         const q=underPoint(segments,tt,reverse);
         glowDot(q.x,q.y,14-k*.45,rgb,intensity*(1-k/17));
       }
       glowDot(head.x,head.y,25,rgb,intensity);
       glowDot(head.x,head.y,44,rgb,intensity*.26*headBoost);
       ctx.restore();
     };

     /* 5.4.9 — trajeto assimétrico sobre as fitas douradas.
        Energia elétrica passando pelo fio / equilibrista na corda bamba:
        o ponto avança pela fita com balanço perpendicular oscilante + tremor
        de alta frequência (faíscas) + lado preferido fixo (assimetria total).
        under=true desloca o trajeto para a face de baixo da fita ("por baixo");
        reverse=true percorre o mesmo caminho em sentido inverso. */
     const trailPoint=(segments,tt,reverse,under,seed)=>{
       const base=pointOn(segments,tt,reverse);
       const a=pointOn(segments,Math.max(.0005,tt-.006),reverse);
       const b=pointOn(segments,Math.min(.9994,tt+.006),reverse);
       const dx=b.x-a.x,dy=b.y-a.y,L=Math.hypot(dx,dy)||1;
       const px=-dy/L,py=dx/L;
       const env=Math.sin(tt*Math.PI);
       const wob=(Math.sin(tt*24+seed)*.6+Math.sin(tt*6.5+seed*2)*.4)*env
                +Math.sin(tt*89+seed*7)*Math.sin(tt*43+seed*3)*.20;
       const side=under?-1:1;
       const bias=(Math.sin(seed*1.7)*.5+.5)*.8;
       return {
         x:base.x+px*(wob*18+side*bias*9),
         y:base.y+py*(wob*18+side*bias*9)
       };
     };
     const drawEnergy=(segments,progress,rgb,intensity,opts={})=>{
       const {reverse=false,under=false,seed=0}=opts;
       const u=Math.max(0,Math.min(.9999,progress));
       ctx.save();
       ctx.globalCompositeOperation='lighter';
       for(let k=0;k<16;k++){
         const tt=Math.max(0,u-k*.013);
         const q=trailPoint(segments,tt,reverse,under,seed);
         glowDot(q.x,q.y,13-k*.42,rgb,intensity*(1-k/18));
       }
       const head=trailPoint(segments,u,reverse,under,seed);
       glowDot(head.x,head.y,26,rgb,intensity);
       for(let f=0;f<3;f++){
         const fu=u-(f+1)*.06;
         if(fu<=0)continue;
         const st=trailPoint(segments,fu,reverse,under,seed+7+f);
         glowDot(st.x,st.y,6.5+f*1.6,rgb,intensity*.45);
       }
       ctx.restore();
     };

     /* As três fitas douradas reais que saem do conjunto DNA/K7.
        Os pontos foram calibrados na arte 1313x946. */
     const ribbon1=[
       [{x:435,y:314},{x:400,y:292},{x:355,y:286},{x:318,y:272}],
       [{x:318,y:272},{x:287,y:258},{x:275,y:244},{x:252,y:250}]
     ];
     const ribbon2=[
       [{x:430,y:332},{x:389,y:352},{x:350,y:323},{x:315,y:311}],
       [{x:315,y:311},{x:281,y:300},{x:264,y:336},{x:230,y:322}],
       [{x:230,y:322},{x:205,y:312},{x:205,y:286},{x:237,y:273}]
     ];
     /* 5.4.15 — ribbon3 sobre o DOURADO real da arte: sobe ao braço esquerdo
        da fita DNA (442,310), cruza o micro-vão (comp10→comp11) e desce o
        ESQUELETO da haste da K7 (tracer confirmado pixel a pixel no ouro),
        terminando na base (249,336) — de onde o mergulho entra POR BAIXO. */
     const ribbon3=[
       [{x:442,y:310},{x:429,y:310},{x:417,y:308},{x:405,y:307}],
       [{x:405,y:307},{x:381,y:303},{x:347,y:298},{x:310,y:294}],
       [{x:310,y:294},{x:298,y:289},{x:286,y:284},{x:275,y:280}],
       [{x:275,y:280},{x:268,y:288},{x:266,y:296},{x:264,y:304}],
       [{x:264,y:304},{x:252,y:309},{x:242,y:313},{x:231,y:316}],
       [{x:231,y:316},{x:231,y:322},{x:231,y:326},{x:233,y:328}],
       [{x:233,y:328},{x:241,y:331},{x:247,y:333},{x:249,y:336}]
     ];

     const drawK7=(u)=>{
       if(u<=0||u>=1)return;
       const e=Math.sin(Math.PI*u);
       softEllipse(170,194,150,105,s,e*.34);
       softEllipse(170,194,120,80,p,e*.18);
       glowDot(138,185,38,s,e*.85);
       glowDot(221,196,38,s,e*.85);
       // HOTFIX 4.2.9: removido o reflexo vertical branco esquerda -> direita.
       // Mantém somente a intensificação localizada da K7 e das bobinas.
     };

     const drawTitleGlow=(u,finalPass=false)=>{
       if(u<=0||u>=1)return;

       const orbit=(cx,cy,rx,ry,q,reverse,rgb)=>{
         const ang=(reverse?-1:1)*q*Math.PI*2;
         // um único ponto principal + cauda curta alinhada
         for(let k=7;k>=0;k--){
           const aa=ang-(reverse?-1:1)*k*.12;
           const fade=(1-k/9);
           glowDot(cx+Math.cos(aa)*rx,cy+Math.sin(aa)*ry,
                   10+k*.25,rgb,fade*.68);
         }
         glowDot(cx+Math.cos(ang)*rx,cy+Math.sin(ang)*ry,17,rgb,.98);
       };

       // 360° sobre o X — ~0,50 s.
       if(u<.25){
         const q=u/.25;
         orbit(1015,185,42,54,q,false,s);
         return;
       }

       // LOGOS — primeiro movimento 360° — ~0,50 s.
       if(u<.50){
         const q=(u-.25)/.25;
         orbit(845,190,150,34,q,true,p);
         return;
       }

       // LOGOS — segundo movimento 360° — ~0,50 s, sentido contrário.
       if(u<.75){
         const q=(u-.50)/.25;
         orbit(845,190,150,34,q,false,s);
         return;
       }

       // Vai diretamente ao topo do DNA.
       const q=(u-.75)/.25;
       const p0={x:695,y:190},p1={x:650,y:145},p2={x:590,y:78},p3={x:525,y:55};
       const z=bez(p0,p1,p2,p3,q);
       for(let k=7;k>=0;k--){
         const qq=Math.max(0,q-k*.035);
         const zz=bez(p0,p1,p2,p3,qq);
         glowDot(zz.x,zz.y,11,s,(1-k/9)*.66);
       }
       glowDot(z.x,z.y,17,s,.96);
     };

     const drawMenuFlow=(u)=>{
       if(u<=0||u>=1)return;
       const e=Math.sin(Math.PI*u);

       // Somente a faixa inferior mostrada na imagem:
       // BÍBLIA -> ESTUDO -> PREGAÇÃO -> AVIVAMENTO.
       const p0={x:260,y:760},p1={x:465,y:760},p2={x:710,y:760},p3={x:950,y:760};
       for(let k=0;k<13;k++){
         const tt=Math.max(0,u-k*.024);
         const q=bez(p0,p1,p2,p3,tt);
         glowDot(q.x,q.y,15-k*.55,k%2?s:p,e*(1-k/15)*.70);
       }
       const q=bez(p0,p1,p2,p3,Math.min(1,u));
       glowDot(q.x,q.y,26,s,e*.84);

       const centers=[
         {x:285,y:760},{x:505,y:760},{x:720,y:760},{x:930,y:760}
       ];
       centers.forEach((pt,i)=>{
         const target=.06+i*.30;
         const hit=Math.max(0,1-Math.abs(u-target)/.10);
         if(hit>0)glowDot(pt.x,pt.y,30,s,hit*.68);
       });
     };

     const drawConnector=(u,a,b,c,d,rgb,intensity)=>{
       if(u<=0||u>=1)return;
       const e=Math.sin(Math.PI*u);
       for(let k=0;k<10;k++){
         const tt=Math.max(0,u-k*.024);
         const q=bez(a,b,c,d,tt);
         glowDot(q.x,q.y,16-k*.6,rgb,e*(1-k/12)*intensity);
       }
     };

     /* 5.4.15 — clímax centrado no MIOLO do livro aberto real (~443,438),
        mais forte e contido; os raios nascem do centro das páginas. */
     const drawBible=(u)=>{
       if(u<=0||u>=1)return;
       const e=Math.sin(Math.PI*Math.min(1,u));
       softEllipse(443,438,178,92,s,e*.66);
       softEllipse(443,438,130,64,p,e*.34);
       glowDot(443,440,58,s,e*1.0);
       // raios que nascem no centro das páginas
       ctx.save();ctx.translate(443,436);
       ctx.globalCompositeOperation='lighter';
       for(let i=-4;i<=4;i++){
         const ang=-Math.PI/2+i*.13;
         const len=118+Math.abs(i)*18;
         const g=ctx.createLinearGradient(0,0,Math.cos(ang)*len,Math.sin(ang)*len);
         g.addColorStop(0,`rgba(255,255,255,${e*.78})`);
         g.addColorStop(.25,rgba(s,e*.46));
         g.addColorStop(1,rgba(s,0));
         ctx.strokeStyle=g;ctx.lineWidth=3.6-Math.abs(i)*.22;
         ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(Math.cos(ang)*len,Math.sin(ang)*len);ctx.stroke();
       }
       ctx.restore();
       if(u>.58){
         const c=(u-.58)/.42;
         glowDot(443,440,110+116*c,s,Math.min(1,c*1.28));
         glowDot(443,440,74+72*c,p,Math.min(.85,c));
       }
     };

     const frame=(now)=>{
       const t=(now-start)/duration;
       ctx.clearRect(0,0,W,H);
       ctx.globalCompositeOperation='lighter';

       // 1 — DESCE PELA LOGO DO DNA (fita verde + dourada), em velocidade uniforme.
       const dnaT=Math.min(1,Math.max(0,t/.20));
       if(t<.20){
         const pulse=.24+.46*Math.sin(Math.PI*Math.min(1,dnaT));
         softEllipse(430,205,190,190,p,pulse*.24);
         softEllipse(430,205,180,185,s,pulse*.18);
         drawTravel(green,Math.min(1,dnaT*1.05),p,1.0);
         drawTravel(gold,Math.min(1,Math.max(0,dnaT-.05)*1.10),s,1.0);
       }
       if(t>.035 && t<.20){
         const u=(t-.035)/.165;
         drawTravel(green,Math.min(1,u),p,.62);
         drawTravel(gold,Math.min(1,u),s,.62);
       }

       // DNA -> FUSÃO: os dois flashes que desceram o DNA tornam-se UM único
       // brilho dourado no ponto de encontro, pronto para percorrer a fita.
       if(t>.15 && t<.24){
         const u=(t-.15)/.09;
         const e=Math.sin(Math.PI*u);
         // halo dourado que cresce envolvendo o ponto de encontro
         softEllipse(430,372,72+26*e,48+18*e,s,e*.38);
         // os DOIS flashes convergem para o centro — viram um
         const spread=(1-e)*16;
         glowDot(430-spread,372,16+10*e,s,e*.85);
         glowDot(430+spread,372,16+10*e,s,e*.85);
         // núcleo único dourado
         glowDot(430,372,26+14*e,s,e);
         glowDot(430,372,14+9*e,s,e*1.15);
       }
       // a luz única desliza do ponto de encontro ao braço esquerdo da fita.
       if(t>.19 && t<.245){
         const u=(t-.19)/.055;
         drawConnector(u,{x:430,y:373},{x:436,y:352},{x:440,y:330},{x:442,y:310},s,.95);
       }

       // 2 — IDA pela fita que sai de baixo, COM SIMETRIA E PROPRIEDADE:
       //     a luz única percorre devagar a fita dourada inferior até a K7.
       if(t>.21 && t<.46){
         const u=(t-.21)/.25;
         const sm=u*u*(3-2*u);
         const prog=Math.min(1,sm*1.04);
         const boost=.78+.22*Math.sin(Math.PI*Math.min(1,prog*1.7));
         drawRibbonTrail(ribbon3,prog,s,.96,false,boost);
       }

       // 3 — adentra POR DEBAIXO: da base da haste (249,336) mergulha e entra
       //     pela base da K7 (210,240), que acende por dentro logo em seguida.
       if(t>.44 && t<.52){
         const u=(t-.44)/.08;
         // 5.4.15 — mergulho alinhado ao ouro: desce o fim da ribbon3 (base da
         // haste) e entra na K7 PELA BASE, tocando o dourado — sem teleporte.
         drawConnector(u,{x:249,y:336},{x:234,y:308},{x:219,y:266},{x:210,y:240},s,.98);
       }

       // 4 — K7 acende por dentro, de forma elegante (pulso único e suave).
      drawK7((t-.50)/.24);
      if(t>.50 && t<.74){
        const u=(t-.50)/.24;
        const e=.82+.18*Math.sin(Math.PI*u);
        glowDot(138,185,42,s,e);
        glowDot(221,196,42,s,e);
        softEllipse(180,205,124,70,s,.30+.10*Math.sin(Math.PI*u));
      }

      // 5 — (5.4.155) SEM o vai-e-volta pela fita dourada: a luz NÃO refaz o
      //     caminho de volta. Depois de acesa, a K7 sustenta o brilho enquanto
      //     UM único fio contínuo desce dela direto ao miolo do livro aberto —
      //     um só sentido, ritmo uniforme (pedido: efeito mais elegante).
      if(t>.64 && t<.90){
        const u=(t-.64)/.26;
        const sm=u*u*(3-2*u);
        const e=Math.sin(Math.PI*Math.min(1,sm*1.10));
        const K0={x:198,y:236},K1={x:258,y:330},K2={x:330,y:404},K3={x:438,y:445};
        for(let k=0;k<20;k++){
          const tt=Math.max(0,sm-k*.020);
          const q=bez(K0,K1,K2,K3,Math.min(1,tt));
          glowDot(q.x,q.y,15-k*.42,s,e*(1-k/22));
        }
        const q=bez(K0,K1,K2,K3,Math.min(1,sm));
        glowDot(q.x,q.y,28,s,e);
        glowDot(q.x,q.y,46,s,e*.30);
      }

      // 6 — Bíblia: clímax final, ênfase sustentada (sem voltar à fita).
      drawBible((t-.84)/.16);
      if(t>.88 && t<1){
        const u=(t-.88)/.12;
        const e=Math.min(1,u/.22);
        softEllipse(443,438,170,98,s,e*.60);
        softEllipse(443,438,120,66,p,e*.34);
        glowDot(443,438,90,s,e);
        glowDot(443,438,54,s,e*1.18);
        glowDot(443,438,26,p,e*.88);
      }

      if(t<1){
         requestAnimationFrame(frame);
       }else{
         canvas.classList.add('is-ending');
         setTimeout(()=>canvas.remove(),500);
       }
     };
     requestAnimationFrame(frame);
   };
   if(splash){
     splash.classList.add('is-done');
     setTimeout(()=>{splash.remove();requestAnimationFrame(()=>requestAnimationFrame(startHomeFx));},620);
   }else{
     requestAnimationFrame(()=>requestAnimationFrame(startHomeFx));
   }
 },wait);
}
