function openHomeActionsEditor(focusId=""){
 document.querySelector("#homeActionEditorBackdrop")?.remove();const actions=homeActions();document.body.insertAdjacentHTML("beforeend",homeActionEditorMarkup(actions));
 const bg=document.querySelector("#homeActionEditorBackdrop"),close=()=>{document.removeEventListener("keydown",onKey);bg?.remove()},onKey=e=>{if(e.key==="Escape")close()};document.addEventListener("keydown",onKey);
 bg?.addEventListener("click",e=>{if(e.target===bg)close()});bg?.querySelectorAll("[data-home-editor-close]").forEach(b=>b.addEventListener("click",close));
 bg?.querySelectorAll('[data-home-edit-field="type"]').forEach(s=>s.addEventListener("change",()=>{s.closest(".home-edit-row").dataset.actionType=s.value}));
 bg?.querySelector("[data-home-editor-save]")?.addEventListener("click",()=>{const next=actions.map((old,i)=>{const row=bg.querySelector(`[data-home-edit-row="${i}"]`),val=name=>row.querySelector(`[data-home-edit-field="${name}"]`)?.value?.trim()||"",type=val("type")||"view";if(old.id==="about"||old.zone==="about"){const ap=row.querySelector('[data-home-edit-field="aboutpage"]')?.value?.trim();if(ap)Store.set("logosAboutPageV1",ap)}return Object.assign({},old,{icon:val("icon")||"✦",label:val("label")||"Atalho",subtitle:val("subtitle"),type,target:type==="view"?val("view"):type==="link"?val("link"):val("popup")})});Store.set("homeActionButtonsV1",next);close();render("dashboard")});
 bg?.querySelector("[data-home-editor-reset]")?.addEventListener("click",()=>{if(!confirm("Restaurar todos os textos e ações da Home?"))return;Store.set("homeActionButtonsV1",homeActionDefaults());Store.del("logosAboutPageV1");close();render("dashboard")});
 setTimeout(()=>{const row=focusId?bg?.querySelector(`[data-home-action-id="${CSS.escape(focusId)}"]`):bg?.querySelector(".home-edit-row");row?.classList.add("home-edit-row-focus");row?.scrollIntoView({block:"center",behavior:"smooth"});row?.querySelector('input[data-home-edit-field="label"]')?.focus()},40);
}
function bindHomeDashboard(){
 document.querySelectorAll("[data-home-action]").forEach(b=>{
  let holdTimer=null,startX=0,startY=0;
  const cancelHold=()=>{if(holdTimer){clearTimeout(holdTimer);holdTimer=null}};
  const edit=e=>{e?.preventDefault?.();e?.stopPropagation?.();cancelHold();openHomeActionsEditor(b.dataset.homeAction)};
  b.addEventListener("click",e=>{e.preventDefault();e.stopPropagation();if(b.dataset.homeSuppressClick==="1"){delete b.dataset.homeSuppressClick;return}if(e.altKey||e.shiftKey)return edit(e);runHomeAction(b.dataset.homeAction)});
  b.addEventListener("contextmenu",edit);
  b.addEventListener("pointerdown",e=>{if(e.pointerType==="mouse")return;startX=e.clientX;startY=e.clientY;cancelHold();holdTimer=setTimeout(()=>{b.dataset.homeSuppressClick="1";setTimeout(()=>{delete b.dataset.homeSuppressClick},1200);navigator.vibrate?.(25);edit(e)},650)});
  b.addEventListener("pointermove",e=>{if(Math.abs(e.clientX-startX)>12||Math.abs(e.clientY-startY)>12)cancelHold()});
  ["pointerup","pointercancel","pointerleave"].forEach(name=>b.addEventListener(name,cancelHold));
 });
 document.querySelectorAll("[data-home-system-details]").forEach(b=>b.addEventListener("click",e=>{e.preventDefault();e.stopPropagation();openHomeSystemDetails()}));
 document.querySelectorAll("[data-home-edit-actions]").forEach(b=>b.addEventListener("click",e=>{e.preventDefault();e.stopPropagation();openHomeActionsEditor()}));
 if(window.__logosHomeEditKey)document.removeEventListener("keydown",window.__logosHomeEditKey);
 window.__logosHomeEditKey=e=>{if(App.view==="dashboard"&&e.altKey&&String(e.key).toLowerCase()==="e"){e.preventDefault();openHomeActionsEditor()}};
 document.addEventListener("keydown",window.__logosHomeEditKey);
 refreshSystemSummary();
}
