   try{const rr=await smartBibleRef(`${p.book} ${p.chapter}`);if(!rr.length)return;current=rr;if($("#bRef"))$("#bRef").value=`${p.book} ${p.chapter}`;renderBibleVerses(rr);bxFocusVerse(p.ref)}catch(_){}
