   modal.querySelectorAll("[data-bm-remove]").forEach(b=>b.onclick=()=>{let a=bxBookmarksGet().filter(x=>x.ref!==b.dataset.bmRemove);localStorage.setItem(bxBookmarksKey,JSON.stringify(a));bxRenderBookmarks()});
