   $("#bxDnaPack")?.addEventListener("click",async()=>{
     const md=bxSnapshotMarkdown(snap),safe=v.ref.replace(/[^\wÀ-ÿ]+/g,"-");
     bxDownloadText(`biblia-x-estudo-${safe}.md`,md,"text/markdown");
     $("#bxVcStatus").textContent="✓ Pacote de estudo gerado";
   });
