   body.innerHTML=`<div class="bx-vc-verse"><b>${escapeHtml(v.ref)}</b><span>${escapeHtml(v.text)}</span></div>
    <section class="bx-verse-resource-feature"><header><span>🎥</span><div><small>MÍDIA X SOBRE A LEITURA</small><h4>Imagens, panoramas 360°, vídeos e áudios</h4><p>A pesquisa será preparada com <b>${escapeHtml(query)}</b>.</p></div></header>
    <div class="bx-verse-media-shortcuts"><span>🖼 Imagens</span><span>🕶️ Panoramas 360°</span><span>🎬 Vídeos</span><span>🎧 Áudios</span></div>
    <footer><button class="btn primary" type="button" data-bx-media-full>🎥 Abrir Mídia X</button><button class="btn secondary" type="button" data-bx-media-atlas>🗺️ Abrir Atlas</button></footer></section>`;
   body.querySelector("[data-bx-media-full]")?.addEventListener("click",()=>{bxCloseVerseContext();activate("media");if($("#bxMediaQuery"))$("#bxMediaQuery").value=query;setTimeout(()=>renderMedia(query),0)});
   body.querySelector("[data-bx-media-atlas]")?.addEventListener("click",()=>{bxCloseVerseContext();activate("maps");if($("#bxMapQuery"))$("#bxMapQuery").value=query;setTimeout(()=>renderMaps(query),0)});
