 const bxRenderLivePanel=(v)=>{
   const body=$("#bxVcBody");if(!body||!v)return;
   body.innerHTML="";
   if(window.BibleXLiveExplorer?.load){
     try{window.BibleXLiveExplorer.load(v.ref)}catch(_){}
   }else{
     body.innerHTML=`<div class="bx-vc-verse"><b>${escapeHtml(v.ref)}</b><span>${escapeHtml(v.text)}</span></div><div class="bx-vc-status">Módulo Bíblia Viva não carregado.</div>`;
   }
 };

 const openVerseContext=(key,v)=>{
   const m=verseTools[key];if(!m||!v)return;
   bxActiveVerse=v;
   const panel=$("#bxVerseContext");if(!panel)return;
   $("#bxVcKind").textContent=`${m[0]} ${key.toUpperCase()}`;
   $("#bxVcTitle").textContent=`${m[1]} • ${v.ref}`;
   $("#bxVcNote").value=bxLoadLocal("note",v.ref,"");
   const fav=bxLoadLocal("fav",v.ref,"0")==="1";
   $("#bxVcFavorite").textContent=fav?"★ Favoritado":"☆ Favoritar";
   $("#bxVcStatus").textContent="";
   panel.dataset.bxResource=key;
   panel.hidden=false;
   bxVerseContextState.wasFull=bxVerseContextIsFullscreen();
   bxVerseContextState.prevScrollY=window.scrollY||0;
   bxVcRenderZoom(bxVcReadZoom());
   const overReading=bxMountVerseContext(panel);
   if(key==="cross")bxRenderCrossPanel(v);
   else if(key==="strong")bxRenderStrongPanel(v);
   else if(key==="lexicon")bxRenderLexiconPanel(v);
   else if(key==="context")bxRenderContextPanel(v);
   else if(key==="comments")bxRenderCommentsPanel(v);
   else if(key==="atlas")bxRenderAtlasPanel(v);
   else if(key==="media")bxRenderMediaVersePanel(v);
   else if(key==="ray")bxRenderRayPanel(v);
   else if(key==="dna")bxRenderDnaPanel(v);
   else if(key==="live")bxRenderLivePanel(v);
   else{
     $("#bxVcBody").innerHTML=`<div class="bx-vc-verse"><b>${escapeHtml(v.ref)}</b><span>${escapeHtml(v.text)}</span></div><div class="bx-vc-grid">${m[2].map(x=>`<button data-bx-resource="${escapeHtml(x)}"><b>${escapeHtml(x)}</b><small>Recurso vinculado a esta passagem</small></button>`).join("")}</div>`;
     $("#bxVcBody").querySelectorAll("[data-bx-resource]").forEach(button=>button.onclick=()=>button.classList.toggle("selected"));
   }
   if(!overReading)panel.scrollIntoView({behavior:"smooth",block:"nearest"});
 };

 document.addEventListener("biblex:fullscreenchange",event=>{
   const panel=$("#bxVerseContext");if(!panel||panel.hidden)return;
   /* 5.4.37 — ao entrar/sair de tela cheia, re-monta o popup no modo correspondente
      (card .bx-vc-popup ↔ modal .bx-fullscreen-resource-modal). */
   bxMountVerseContext(panel);
 });
 document.addEventListener("biblex:pagechange",event=>{if(event.detail?.id&&event.detail.id!=="reader"&&!$("#bxVerseContext")?.hidden)bxCloseVerseContext()});
 document.addEventListener("keydown",event=>{
   const crossReader=$("#bxCrossReaderModal");if(crossReader&&!crossReader.hidden)return;
   if(event.key!=="Escape"||$("#bxVerseContext")?.hidden)return;
   event.preventDefault();event.stopImmediatePropagation();bxCloseVerseContext();
 },true);
 /* 5.4.37 — toolbar do popup de versículo: Tela cheia / Zoom A− A+ / Sair.
    Usa span (não botão) para o percentual e texto sem "a±" para não colidir com o
    hotfix de zoom/tela-cheia global (ui-controls-zoom-fullscreen). */
 document.addEventListener("click",event=>{
   const button=event.target.closest?event.target.closest("[data-bx-vc-action]"):null;
   if(!button)return;
   event.preventDefault();event.stopImmediatePropagation();
   const action=button.dataset.bxVcAction;
   if(action==="fullscreen")bxVcSetFullscreen(!bxVerseContextIsFullscreen());
   else if(action==="smaller")bxVcApplyZoom(bxVcReadZoom()-10);
   else if(action==="larger")bxVcApplyZoom(bxVcReadZoom()+10);
   else if(action==="pct")bxVcApplyZoom(100);
   else if(action==="close")bxCloseVerseContext();
 },true);

