 $("#bMeta").onclick=async()=>{try{const r=await bxFetch(`${bibleApiBase()}/translations`);const j=await r.json();$("#bOut").textContent=`BÍBLIA X • MOTOR INTEGRADO\n${(j.items||[]).map(x=>`${x.short_name}: ${x.status}`).join("\n")}\n\nBanco SQLite interno + fallback IndexedDB.`}catch{const a=await dbAll("verses");$("#bOut").textContent=`BÍBLIA X • BASE LOCAL\nVersículos: ${a.length.toLocaleString("pt-BR")}\nModo: IndexedDB`}};
 $("#bOpen").onclick=async()=>{
   const out=$("#bOut");
   // Se o bRef oculto acabou de ser preenchido por outra ferramenta interna
   // (painel de estudos, sessão restaurada, hash #ref=..., lista de resultados),
   // respeitamos essa referência — ela é completa e confiável. O campo visível
   // de versículo só prevalece quando o usuário está digitando nele; caso
   // contrário, reconstruir pelos seletores sobrescreveria refs externas
   // (ex.: "Números 35:30" vinda do painel de concordância).
   const hidden=String($("#bRef")?.value||"").trim();
   const hiddenState=currentRefState();
   const typingVerse=document.activeElement===$("#bVerse");
   if(typingVerse && hiddenState && hidden){
     // Usuário digitando no campo visível de versículo.
     if(!bxV158PrepareRef())return;
   }else if(!hidden || !hiddenState){
     if(!bxV158PrepareRef()){
       out.innerHTML='<div class="bx-v158-error">⚠ Versículo inválido. Use, por exemplo, <b>16</b> ou <b>16-18</b>.</div>';
       bxV158UpdateMode();
       return;
     }
   }
   // Caso contrário, hidden é uma referência completa e confiável (ex.: vinda do
   // painel de estudos). Os seletores são sincronizados após o carregamento.
   /* 5.4.169 — NÃO apaga mais o texto ("Carregando passagem..."): o versículo
      atual continua na tela enquanto o próximo carrega. Antes, ao limpar o
      conteúdo, o scrollHeight despencava e criava o vão/sombra de fora a fora
      no overscroll. Agora uma pill pequena avisa e some na renderização/erro. */
   if(window.__bxChapterLoading)window.__bxChapterLoading.show(String($("#bRef")?.value||"").trim());
   try{
     current=await smartBibleRef($("#bRef").value);
     if(current.length){
       await syncBookChapterSelectors(current[0].book,current[0].chapter);
       bxV158SyncVisibleVerse(current);if($("#bChapterTitle"))$("#bChapterTitle").textContent=current.length===1?current[0].ref:`${current[0].book} ${current[0].chapter}`;
     }
     renderBibleVerses(current);
     if(window.__bxChapterLoading)window.__bxChapterLoading.hide();
   }catch(e){
     current=[];
     if(window.__bxChapterLoading)window.__bxChapterLoading.hide();
     out.textContent=`Não foi possível abrir a passagem. ${e.message||""}`;
   }
   // 5.4.140: troca de capítulo no celular (swipe/botões Anterior/Próximo)
   // deve começar do versículo 1 — o flag é setado por quem clicou
   // #bPrevChapter/#bNextChapter (listener de captura no fim do app).
   // 5.4.141: em vez do #bOut, rola o PRIMEIRO VERSÍCULO — assim o texto
   // começa logo no versículo 1 (o CSS mobile dá scroll-margin-top para
   // ficar abaixo do header/topbar fixos). (isMobile não existe neste
   // escopo — por isso o matchMedia direto.)
   if(window.__bxScrollTopNext&&window.matchMedia("(max-width:760px)").matches){
     window.__bxScrollTopNext=0;
     const _v=$("#bOut .lmx-bible-v3-verse");
     if(_v)_v.scrollIntoView({block:"start"});
     else{const _bo=$("#bOut");if(_bo)_bo.scrollIntoView({block:"start"});}
   }
 };
