 const BX_SEARCH_X_PAGE_SIZE=250;
 let bxSearchXOffset=0,bxSearchXBusy=false;
 const bxSearchXPopulateBooks=async()=>{
   const select=$("#bxSearchXBook");if(!select)return;
   const translation=$("#bxSearchXVersion")?.value||selectedTranslation();
   try{
     const response=await bxFetch(`${bibleApiBase()}/books?translation=${encodeURIComponent(translation)}`),page=await response.json();
     const currentValue=select.value;
     select.innerHTML='<option value="">Todos os livros</option>'+(page.items||[]).map(item=>`<option value="${escapeHtml(item.code)}">${escapeHtml(translation==="engwebp"?(item.name_en||item.code):(item.name_pt||item.code))}</option>`).join('');
     if([...select.options].some(option=>option.value===currentValue))select.value=currentValue;
   }catch(_){select.innerHTML='<option value="">Livros indisponíveis</option>'}
 };
 const bxSearchXSetKpis=(total=0,books=0,shown=0)=>{if($("#bxSearchXTotal"))$("#bxSearchXTotal").textContent=Number(total).toLocaleString("pt-BR");if($("#bxSearchXBooks"))$("#bxSearchXBooks").textContent=Number(books).toLocaleString("pt-BR");if($("#bxSearchXShown"))$("#bxSearchXShown").textContent=Number(shown).toLocaleString("pt-BR")};
 const bxSearchXOpen=async(v,translation)=>{
   try{
     activate("reader",{smooth:false});
     if($("#bVersion")&&$("#bVersion").value!==translation){$("#bVersion").value=translation;await refreshCount()}
     await syncBookChapterSelectors(v.book,v.chapter);
     if($("#bRef"))$("#bRef").value=v.ref;
     current=await smartBibleRef(v.ref);
     renderBibleVerses(current);
     setTimeout(()=>$("#bOut")?.scrollIntoView({behavior:"smooth",block:"start"}),30);
   }catch(e){bxV159Toast(`Não foi possível abrir ${v.ref}`)}
 };
 const bxSearchXRender=(page,q,translation,mode)=>{
   const out=$("#bxSearchXResults"),rows=page.items||[];if(!out)return;
   const books=new Set(rows.map(row=>row.book));
   bxSearchXSetKpis(page.total??rows.length,page.books_total??books.size,rows.length);
   if(!rows.length){out.innerHTML=`<div class="bx-search-x-empty"><span>🔎</span><h4>Nenhuma ocorrência encontrada</h4><p>Tente outra correspondência, escopo ou uma expressão menor.</p></div>`;return}
   const start=Number(page.offset||0),total=Number(page.total||rows.length),end=start+rows.length;
   out.innerHTML=`<div class="bx-search-x-summary"><div><b>${escapeHtml(q)}</b><span>${total.toLocaleString("pt-BR")} resultado(s) • exibindo ${(start+1).toLocaleString("pt-BR")}–${end.toLocaleString("pt-BR")}</span></div><button type="button" data-search-x-copy>⧉ Copiar esta página</button></div><div class="bx-search-x-list">${rows.map((v,index)=>`<article class="bx-search-x-result"><button type="button" class="bx-search-x-ref" data-search-x-open="${index}">${escapeHtml(v.ref)}</button><p>${bxV159Highlight(v.text,q,mode)}</p><button type="button" data-search-x-open="${index}">Abrir no leitor →</button></article>`).join('')}</div><footer class="bx-search-x-pager"><button class="btn secondary" type="button" data-search-x-page="${Math.max(0,start-BX_SEARCH_X_PAGE_SIZE)}" ${start<=0?'disabled':''}>← Anterior</button><span>Página ${Math.floor(start/BX_SEARCH_X_PAGE_SIZE)+1} de ${Math.max(1,Math.ceil(total/BX_SEARCH_X_PAGE_SIZE))}</span><button class="btn secondary" type="button" data-search-x-page="${start+BX_SEARCH_X_PAGE_SIZE}" ${end>=total?'disabled':''}>Próxima →</button></footer>`;
   out.querySelectorAll('[data-search-x-open]').forEach(button=>button.onclick=()=>bxSearchXOpen(rows[Number(button.dataset.searchXOpen)],translation));
   out.querySelectorAll('[data-search-x-page]').forEach(button=>button.onclick=()=>bxSearchXRun(Number(button.dataset.searchXPage)));
   out.querySelector('[data-search-x-copy]')?.addEventListener('click',async()=>{await bxCopyText(formatVerses(rows));bxV159Toast(`${rows.length} resultados copiados`)});
 };
 const bxSearchXRun=async(offset=0)=>{
   const out=$("#bxSearchXResults"),q=String($("#bxSearchXQuery")?.value||'').trim();if(!out||bxSearchXBusy)return;
   if(!q){out.innerHTML='<div class="bx-search-x-empty"><span>⌨️</span><h4>Informe uma palavra, frase ou referência</h4></div>';$("#bxSearchXQuery")?.focus();return}
   bxSearchXBusy=true;bxSearchXOffset=Math.max(0,Number(offset)||0);out.innerHTML='<div class="bx-search-x-loading"><span>🔎</span><b>Pesquisando nos 66 livros...</b><small>Consultando o índice bíblico pré-instalado.</small></div>';
   const translation=$("#bxSearchXVersion")?.value||selectedTranslation(),scope=$("#bxSearchXScope")?.value||'all',mode=$("#bxSearchXMode")?.value||'phrase',sort=$("#bxSearchXSort")?.value||'canon',book=scope==='book'?$("#bxSearchXBook")?.value||$("#bBook")?.value||'':'';
   try{
     let page;
     if(/(?:^|\s)\d{1,3}(?::\d{1,3}(?:[-–]\d{1,3})?)?\s*$/.test(q)){
       if($("#bVersion"))$("#bVersion").value=translation;
       try{const verses=await apiBibleRef(q);page={items:verses,total:verses.length,offset:0,truncated:false}}catch(_){page=null}
     }
     if(!page)page=await apiBibleSearchPage(q,{translation,limit:BX_SEARCH_X_PAGE_SIZE,offset:bxSearchXOffset,mode,scope,sort,book});
     bxSearchXRender(page,q,translation,mode);
   }catch(e){bxSearchXSetKpis();out.innerHTML=`<div class="bx-search-x-empty"><span>⚠️</span><h4>Pesquisa temporariamente indisponível</h4><p>${escapeHtml(e.message||String(e))}</p></div>`}
   finally{bxSearchXBusy=false}
 };
