 document.querySelectorAll('[data-search-x-scope]').forEach(button=>button.addEventListener('click',()=>{if($("#bxSearchXScope"))$("#bxSearchXScope").value=button.dataset.searchXScope;document.querySelectorAll('[data-search-x-scope]').forEach(item=>item.classList.toggle('active',item===button));if(String($("#bxSearchXQuery")?.value||'').trim())bxSearchXRun(0)}));
