 const crossSource=$("#bxCrossSource"),crossTarget=$("#bxCrossTarget"),crossList=$("#bxCrossList"),crossPreview=$("#bxCrossSourcePreview");
 const renderNaveRows=(items=[],message="")=>{const list=$("#bxNaveResults"),count=$("#bxNaveCount");if(!list)return;if(count)count.textContent=message||`${items.length} tópico${items.length===1?'':'s'} encontrado${items.length===1?'':'s'}`;if(!items.length){list.innerHTML='<div class="bx-cross-empty">Nenhum tópico Nave encontrado.</div>';return}list.innerHTML=items.map(x=>`<article><button type="button" class="bx-nave-topic-open" data-nave-topic="${escapeHtml(x.topic_id)}" data-nave-title="${escapeHtml(x.topic)}"><b>🏷️ ${escapeHtml(x.topic)}</b>${x.section?`<em>${escapeHtml(x.section)}</em>`:""}<small>${x.reference_count?`${x.reference_count} ligações bíblicas`:(x.summary||"Abrir referências do tópico")}</small><span>Ver referências →</span></button></article>`).join("");list.querySelectorAll("[data-nave-topic]").forEach(b=>b.onclick=()=>bxOpenNaveTopic(b.dataset.naveTopic,b.dataset.naveTitle))};
 const openCrossPopup=async(ref)=>{const rows=await smartBibleRef(ref),old=document.getElementById('bxVersePopup');if(old)old.remove();const box=document.createElement('div');box.id='bxVersePopup';box.className='bx-verse-popup';box.innerHTML=`<div class="bx-verse-dialog"><div class="bx-verse-head"><div><span>🔗 Referência</span><h4>${escapeHtml(ref)}</h4></div><button data-close>×</button></div><div class="bx-verse-text">${rows.length?escapeHtml(formatVerses(rows)).replace(/\n/g,'<br>'):'Texto não encontrado na Bíblia local.'}</div><div class="row"><button class="btn primary" data-open-main>Abrir no leitor</button><button class="btn secondary" data-close2>Fechar</button></div></div>`;document.body.appendChild(box);const close=()=>box.remove();box.querySelector('[data-close]').onclick=close;box.querySelector('[data-close2]').onclick=close;box.addEventListener('click',e=>{if(e.target===box)close()});box.querySelector('[data-open-main]').onclick=()=>{if(!rows.length)return;activate('reader');$("#bRef").value=ref;current=rows;renderBibleVerses(rows);close()}};
 const renderCross=async(source)=>{
  if(!crossList)return;source=normalizeBibleRef(source||crossSource?.value);if(crossSource&&source)crossSource.value=source;
  const local=source?await crossBySource(source):[];let passage=[];try{passage=source?await smartBibleRef(source):[]}catch(_){passage=[]}
  const verse=passage[0]||null,[server,nave]=verse?await Promise.all([bxServerCrossrefs(verse),bxServerNave(verse)]):[[],[]];
  const rows=server.map((x,i)=>({id:`tsk:${i}`,target:x.reference,anchor:x.anchor||"",tsk:true}));
  local.forEach(x=>{if(!rows.some(y=>normalizeBibleRef(y.target).toLowerCase()===normalizeBibleRef(x.target).toLowerCase()))rows.push(x)});
  const count=$("#bxCrossCount");if(count)count.textContent=`${server.length} TSK • ${local.length} pessoal${local.length===1?'':'is'}`;
  crossList.innerHTML=rows.length?rows.map(x=>`<article class="bx-cross-item"><button class="bx-cross-open" data-cross-open="${escapeHtml(x.target)}"><span>↗</span><div><strong>${escapeHtml(x.target)}</strong><small>${x.tsk?`TSK${x.anchor?` • âncora original: ${escapeHtml(x.anchor)}`:""}`:"Referência adicionada por você"}</small></div></button>${x.tsk?'':`<button class="bx-cross-remove" data-cross-remove="${escapeHtml(x.id)}" title="Remover">×</button>`}</article>`).join(''):'<div class="bx-cross-empty">Nenhuma referência encontrada para esta passagem.</div>';
  crossList.querySelectorAll('[data-cross-open]').forEach(b=>b.onclick=()=>openCrossPopup(b.dataset.crossOpen));crossList.querySelectorAll('[data-cross-remove]').forEach(b=>b.onclick=async()=>{await crossDelete(b.dataset.crossRemove);await renderCross(source)});
  renderNaveRows(nave,verse?`${nave.length} tópico${nave.length===1?'':'s'} ligado${nave.length===1?'':'s'} a ${verse.ref}`:"Carregue uma passagem para consultar");
 };
