 const commentDetail=row=>{const box=$("#bxCommentsDetail");if(!box||!row)return;const installed=row.server===true;box.innerHTML=`<div class="bx-comments-detail-head"><div><span>💬 ${escapeHtml(commentTypeLabel(row.type))}${installed?' • PRÉ-INSTALADO':' • PESSOAL'}</span><h4>${escapeHtml(row.title)}</h4><small>${escapeHtml([row.reference,row.authorLabel,row.sourceLabel].filter(Boolean).join(' • '))}</small></div>${installed?'<span class="bx-comment-installed">🔒 Fonte preservada</span>':'<button class="btn danger" data-comment-delete>Excluir</button>'}</div>${row.language==='en'?'<div class="bx-comments-language">Conteúdo clássico preservado em inglês porque esta seção ainda não possui tradução PT-BR em cache.</div>':''}<article class="bx-comments-content">${escapeHtml(row.content).replace(/\n/g,'<br>')}</article>${row.tags?.length?`<section class="bx-comments-tags"><span>Palavras-chave</span><div>${row.tags.map(x=>`<i>${escapeHtml(x)}</i>`).join('')}</div></section>`:''}${row.refs?.length?`<section class="bx-comments-refs"><span>Referências relacionadas</span><div>${row.refs.map(x=>`<button data-comment-ref="${escapeHtml(x)}">${escapeHtml(x)}</button>`).join('')}</div></section>`:''}<div class="row bx-comments-actions"><button class="btn secondary" data-comment-copy>Copiar</button>${installed?'':'<button class="btn secondary" data-comment-edit>Editar</button>'}${row.reference?`<button class="btn primary" data-comment-open>📖 Abrir passagem</button>`:''}<button class="btn secondary" data-comment-strong>🇬🇷🇮🇱 Strong</button><button class="btn secondary" data-comment-lex>📚 Léxico</button><button class="btn secondary" data-comment-context>🧭 Contexto</button><button class="btn secondary" data-comment-dna>🧬 DNA K7</button></div>`;box.querySelector('[data-comment-delete]')?.addEventListener('click',async()=>{if(!confirm('Excluir este comentário local?'))return;await commentsDelete(row.id);box.innerHTML='<div class="bx-comments-detail-empty"><span>💬</span><h4>Comentário removido</h4></div>';await renderComments()});box.querySelector('[data-comment-copy]')?.addEventListener('click',()=>navigator.clipboard?.writeText(`${row.title}\n${row.reference?row.reference+'\n':''}\n${row.content}`));box.querySelector('[data-comment-edit]')?.addEventListener('click',async()=>{const title=prompt('Título do comentário:',row.title);if(title===null)return;const content=prompt('Conteúdo do comentário:',row.content);if(content===null)return;await commentsPutMany([{...row,title,content,server:false}]);await renderComments();const updated=(await commentsAll()).find(x=>x.id===row.id)||{...row,title,content,server:false};commentDetail(updated)});box.querySelector('[data-comment-open]')?.addEventListener('click',async()=>{activate('reader');$("#bRef").value=row.reference;current=await smartBibleRef(row.reference);renderBibleVerses(current)});box.querySelectorAll('[data-comment-ref]').forEach(b=>b.onclick=async()=>{activate('reader');$("#bRef").value=b.dataset.commentRef;current=await smartBibleRef(b.dataset.commentRef);renderBibleVerses(current)});box.querySelector('[data-comment-strong]')?.addEventListener('click',()=>{activate('strong');setTimeout(()=>renderStrong(),0)});box.querySelector('[data-comment-lex]')?.addEventListener('click',()=>{activate('lexicon');setTimeout(()=>renderLexicon(),0)});box.querySelector('[data-comment-context]')?.addEventListener('click',()=>{activate('context');if($("#bxContextQuery")&&row.reference)$("#bxContextQuery").value=row.reference;setTimeout(()=>renderContext(row.reference),0)});box.querySelector('[data-comment-dna]')?.addEventListener('click',()=>{activate('dna');if($("#bxDnaRef")&&row.reference)$("#bxDnaRef").value=row.reference;setTimeout(()=>{dnaLoadSaved();if(row.reference)dnaUseCurrent(row.reference)},0)})};
 const renderComments=async(q='')=>{const list=$("#bxCommentsList");if(!list)return;const term=String(q||$("#bxCommentsQuery")?.value||'').trim();list.innerHTML='<div class="bx-comments-empty">Pesquisando fontes pré-instaladas e comentários pessoais...</div>';try{const params=new URLSearchParams({q:term,type:commentType,limit:'250'});const [response,personalAll]=await Promise.all([bxFetch(`/api/bible/commentary/search?${params}`).catch(()=>null),commentsAll().catch(()=>[])]);const page=response?.ok?await response.json():{items:[],total:0};let personal=personalAll.map(row=>({...row,server:false}));const key=bxV159Norm(term);if(commentType!=='all')personal=personal.filter(row=>row.type===commentType);if(key)personal=personal.filter(row=>bxV159Norm([row.reference,row.type,row.title,row.content,row.authorLabel,row.sourceLabel,...(row.tags||[]),...(row.refs||[])].join(' ')).includes(key));const installed=(page.items||[]).map(row=>({...row,server:true})),rows=[...installed,...personal];rows.sort((a,b)=>(a.server===b.server?0:a.server?-1:1)||String(a.reference||'').localeCompare(String(b.reference||''),'pt-BR'));const count=$("#bxCommentsCount");if(count)count.textContent=`${installed.length} pré-instalado${installed.length===1?'':'s'} • ${personal.length} pessoa${personal.length===1?'l':'is'}`;if(!rows.length){list.innerHTML='<div class="bx-comments-empty">Nenhum comentário localizado. Tente uma referência (ex.: João 3:16), o nome de um livro ou outra palavra.</div>';return}list.innerHTML=rows.slice(0,400).map(x=>`<button class="bx-comments-item ${x.server?'installed':'personal'}" data-comment-id="${escapeHtml(x.id)}" data-comment-server="${x.server?'1':'0'}"><span>${({executivo:'⚡',exegetico:'🔎',hermeneutico:'📐','historico-cultural':'🏺',pastoral:'❤️',homiletico:'🎙'}[x.type]||'💬')}</span><div><strong>${escapeHtml(x.title)}</strong><small>${escapeHtml([x.reference,commentTypeLabel(x.type),x.server?'Pré-instalado':'Pessoal'].filter(Boolean).join(' • '))}</small><p>${escapeHtml(String(x.content||'').slice(0,150))}${String(x.content||'').length>150?'…':''}</p></div></button>`).join('');list.querySelectorAll('[data-comment-id]').forEach(button=>button.onclick=()=>{list.querySelectorAll('.bx-comments-item').forEach(item=>item.classList.toggle('active',item===button));commentDetail(rows.find(row=>row.id===button.dataset.commentId&&String(row.server?1:0)===button.dataset.commentServer))});if(rows.length===1)list.querySelector('[data-comment-id]')?.click()}catch(e){list.innerHTML=`<div class="bx-comments-empty">Falha ao abrir Comentários X: ${escapeHtml(e.message||String(e))}</div>`}};
 $("#bxCommentsFind")?.addEventListener('click',()=>renderComments($("#bxCommentsQuery").value));$("#bxCommentsQuery")?.addEventListener('keydown',e=>{if(e.key==='Enter')renderComments(e.target.value)});document.querySelectorAll('[data-comment-type]').forEach(b=>b.onclick=()=>{commentType=b.dataset.commentType;document.querySelectorAll('[data-comment-type]').forEach(x=>x.classList.toggle('active',x===b));renderComments()});
 $("#bxCommentsNew")?.addEventListener('click',async()=>{const reference=normalizeBibleRef(prompt('Referência bíblica:',current?.length?`${current[0].book} ${current[0].chapter}:${current[0].verse}`:($("#bRef")?.value||''))||'');if(reference===null)return;const title=prompt('Título do comentário:','Novo comentário');if(title===null)return;const type=prompt('Tipo: executivo, exegetico, hermeneutico, historico-cultural, pastoral ou homiletico','executivo');if(type===null)return;const content=prompt('Conteúdo do comentário:','');if(!content)return;const n=await commentsPutMany([{id:`user-${Date.now()}`,reference,type,title,content,authorLabel:'Comentário pessoal',sourceLabel:'Bíblia X'}]);if(n)await renderComments()});
 $("#bxCommentsExample")?.addEventListener('click',async()=>{await commentsPutMany([{id:'cm-joao316-exec',reference:'João 3:16',type:'executivo',title:'O centro do anúncio',content:'A passagem concentra a iniciativa divina, o amor como origem da ação e a resposta de fé. Use este comentário como síntese de estudo, não como substituto da leitura do contexto.',authorLabel:'Comentário executivo',sourceLabel:'Bíblia X • exemplo',tags:['amor','fé','evangelho'],refs:['João 3:14-18','Romanos 5:8']},{id:'cm-isaias6-exeg',reference:'Isaías 6',type:'exegetico',title:'Santidade, purificação e envio',content:'O movimento literário passa da visão da santidade para a consciência de impureza, da purificação para a disponibilidade ao envio. A estrutura do capítulo ajuda a preservar a progressão do texto antes de qualquer aplicação homilética.',authorLabel:'Comentário exegético',sourceLabel:'Bíblia X • exemplo',tags:['santidade','chamado','missão'],refs:['Isaías 6:1-8']},{id:'cm-isaias6-hom',reference:'Isaías 6:8',type:'homiletico',title:'Da visão ao envio',content:'Possível eixo homilético: contemplação → convicção → purificação → escuta → resposta. O desenvolvimento deve nascer do texto e só então caminhar para aplicações e chamado.',authorLabel:'Comentário homilético',sourceLabel:'Bíblia X • exemplo',tags:['estrutura','pregação','chamado'],refs:['Isaías 6:1-8']}]);await renderComments()});
 $("#bxCommentsImport")?.addEventListener('click',async()=>{const f=$("#bxCommentsFile")?.files?.[0];if(!f)return alert('Escolha um JSON de comentários.');try{const j=JSON.parse(await f.text()),rows=Array.isArray(j)?j:(j.comments||j.comentarios||[]),n=await commentsPutMany(rows);alert(`${n} comentário(s) importado(s).`);await renderComments()}catch(e){alert('Falha ao importar comentários: '+e.message)}});$("#bxCommentsExport")?.addEventListener('click',async()=>download('biblia-x-comentarios.json',JSON.stringify(await commentsAll(),null,2),'application/json'));$("#bxCommentsClear")?.addEventListener('click',async()=>{if(!confirm('Limpar todos os comentários locais?'))return;await commentsClear();await renderComments();const d=$("#bxCommentsDetail");if(d)d.innerHTML='<div class="bx-comments-detail-empty"><span>💬</span><h4>Banco de comentários limpo</h4></div>'});
