 const bxV167RenderTours=async()=>{const grid=$('#bxV167TourGrid');if(!grid)return;grid.innerHTML=bxV167Tours.map(x=>{const u=bxV167Urls(x);return `<article data-v167-id="${escapeHtml(x.id)}"><button type="button" class="bx-v167-tour-cover" data-v167-gallery="${escapeHtml(x.id)}"><span>📍</span><small>Carregando imagem...</small></button><div><b>${escapeHtml(x.name)}</b><small>${escapeHtml(x.hint)}</small></div><nav><button type="button" data-v167-gallery="${escapeHtml(x.id)}">🖼️ Galeria</button><a href="${escapeHtml(u.pano)}" target="_blank" rel="noopener">🕶️ Street View</a><a href="${escapeHtml(u.map)}" target="_blank" rel="noopener">🗺️ Mapa</a><button type="button" data-v167-ref="${escapeHtml(x.ref)}">📖 Bíblia</button></nav></article>`}).join('');grid.querySelectorAll('[data-v167-ref]').forEach(b=>b.onclick=async()=>{const ref=b.dataset.v167Ref;activate('reader');if($('#bRef'))$('#bRef').value=ref;try{const rr=await smartBibleRef(ref);if(rr.length){current=rr;renderBibleVerses(rr)}}catch(_){}});grid.querySelectorAll('[data-v167-gallery]').forEach(b=>b.onclick=()=>{const x=bxV167Tours.find(item=>item.id===b.dataset.v167Gallery);if(x)bxMapExplore({...x,type:'place',region:'Israel',period:'Cenário bíblico',description:x.hint,refs:[x.ref]})});await Promise.allSettled(bxV167Tours.map(async x=>{const cover=grid.querySelector(`[data-v167-id="${x.id}"] .bx-v167-tour-cover`);if(!cover)return;try{const items=await bxPublicMediaSearch(x.name,'image',1),item=items[0];cover.innerHTML=item?`<img loading="lazy" src="${escapeHtml(item.thumb_url||item.original_url)}" alt="${escapeHtml(x.name)}"><span>🖼️ Abrir galeria</span>`:'<span>📍</span><small>Abra a galeria visual</small>'}catch(_){cover.innerHTML='<span>📍</span><small>Abra a galeria visual</small>'}}))};

