 const timelineYearLabel=x=>{if(x.displayDate)return x.displayDate;const one=y=>y===0?'Data não definida':(y<0?`${Math.abs(y)} a.C.`:`${y} d.C.`);return x.endYear&&x.endYear!==x.startYear?`${one(x.startYear)} – ${one(x.endYear)}`:one(x.startYear)};
 const timelineDetail=row=>{const box=$("#bxTimelineDetail");if(!box||!row)return;const chips=(title,items,ico)=>items?.length?`<section class="bx-time-block"><h5>${title}</h5><div>${items.map(x=>`<span>${ico} ${escapeHtml(x)}</span>`).join('')}</div></section>`:'';box.innerHTML=`<div class="bx-time-detail-head"><div><span>${timeTypeIcon(row.type)} ${escapeHtml(timeTypeLabel(row.type))}</span><h4>${escapeHtml(row.title)}</h4><small>${row.approximate?'≈ ':''}${escapeHtml(timelineYearLabel(row))}${row.era?' • '+escapeHtml(row.era):''}</small></div><button class="btn danger" data-time-delete>Excluir</button></div>${row.summary?`<article class="bx-time-summary">${escapeHtml(row.summary).replace(/\n/g,'<br>')}</article>`:''}${chips('Personagens',row.people,'👤')}${chips('Lugares',row.places,'📍')}${chips('Livros relacionados',row.books,'📖')}${row.refs?.length?`<section class="bx-time-refs"><h5>Referências bíblicas</h5><div>${row.refs.map(x=>`<button data-time-ref="${escapeHtml(x)}">${escapeHtml(x)}</button>`).join('')}</div></section>`:''}${chips('Conexões cronológicas',row.related,'↔')}${row.notes?`<section class="bx-time-notes"><h5>Notas</h5><p>${escapeHtml(row.notes)}</p></section>`:''}<div class="row bx-time-actions"><button class="btn secondary" data-time-copy>Copiar ficha</button><button class="btn secondary" data-time-edit>Editar</button><button class="btn secondary" data-time-people>👤 Personagens</button><button class="btn secondary" data-time-map>🗺️ Mapas</button><button class="btn secondary" data-time-context>🧭 Contexto</button><button class="btn secondary" data-time-dna>🧬 DNA K7</button></div>`;box.querySelector('[data-time-delete]')?.addEventListener('click',async()=>{if(!confirm(`Excluir ${row.title} da cronologia local?`))return;await timelineDelete(row.id);box.innerHTML='<div class="bx-timeline-detail-empty"><span>🕰️</span><h4>Registro removido</h4></div>';await renderTimeline()});box.querySelector('[data-time-copy]')?.addEventListener('click',()=>navigator.clipboard?.writeText([row.title,timelineYearLabel(row),row.summary,row.refs?.length&&`Referências: ${row.refs.join(', ')}`].filter(Boolean).join('\n')));box.querySelector('[data-time-edit]')?.addEventListener('click',async()=>{const title=prompt('Título:',row.title);if(title===null)return;const displayDate=prompt('Data exibida:',row.displayDate||timelineYearLabel(row));if(displayDate===null)return;const summary=prompt('Resumo:',row.summary);if(summary===null)return;await timelinePutMany([{...row,title,displayDate,summary}]);await renderTimeline()});box.querySelectorAll('[data-time-ref]').forEach(b=>b.onclick=async()=>{activate('reader');if($("#bRef"))$("#bRef").value=b.dataset.timeRef;current=await bibleRef(b.dataset.timeRef);if($("#bOut"))$("#bOut").textContent=formatVerses(current)||'Passagem não encontrada na Bíblia local.'});box.querySelector('[data-time-people]')?.addEventListener('click',()=>{activate('people');if($("#bxPeopleQuery"))$("#bxPeopleQuery").value=row.people?.[0]||row.title;setTimeout(()=>renderPeople(),0)});box.querySelector('[data-time-map]')?.addEventListener('click',()=>{activate('maps');if($("#bxMapQuery"))$("#bxMapQuery").value=row.places?.[0]||row.title;setTimeout(()=>renderMaps(),0)});box.querySelector('[data-time-context]')?.addEventListener('click',()=>{activate('context');if($("#bxContextQuery"))$("#bxContextQuery").value=row.refs?.[0]||row.title;setTimeout(()=>renderContext(),0)});box.querySelector('[data-time-dna]')?.addEventListener('click',()=>{activate('dna');if($("#bxDnaRef")&&row.refs?.[0])$("#bxDnaRef").value=row.refs[0];setTimeout(()=>dnaLoadSaved(),0)})};
 const renderTimeline=async(q='')=>{const list=$("#bxTimelineList");if(!list)return;let rows=await timelineAll();const term=String(q||$("#bxTimelineQuery")?.value||'').trim().toLowerCase(),era=$("#bxTimelineEra")?.value||'all';if(timelineType!=='all')rows=rows.filter(x=>x.type===timelineType);if(era!=='all')rows=rows.filter(x=>x.era===era);if(term)rows=rows.filter(x=>[x.title,x.type,x.era,x.displayDate,x.summary,x.notes,...(x.people||[]),...(x.places||[]),...(x.books||[]),...(x.refs||[]),...(x.related||[])].some(v=>String(v||'').toLowerCase().includes(term)));rows.sort((a,b)=>Number(a.startYear||0)-Number(b.startYear||0)||String(a.title).localeCompare(String(b.title),'pt-BR'));const c=$("#bxTimelineCount");if(c)c.textContent=`${rows.length} registro${rows.length===1?'':'s'}`;if(!rows.length){list.innerHTML='<div class="bx-timeline-empty">Nenhum registro encontrado na cronologia local.</div>';return}list.innerHTML=`<div class="bx-time-axis"></div>`+rows.slice(0,600).map(x=>`<button class="bx-time-item ${String(x.testament).toUpperCase()==='NT'?'is-nt':'is-at'}" data-time-id="${escapeHtml(x.id)}"><span class="bx-time-dot"></span><div class="bx-time-date">${x.approximate?'≈ ':''}${escapeHtml(timelineYearLabel(x))}</div><div class="bx-time-card"><small>${timeTypeIcon(x.type)} ${escapeHtml(timeTypeLabel(x.type))}</small><strong>${escapeHtml(x.title)}</strong>${x.summary?`<p>${escapeHtml(x.summary.slice(0,145))}${x.summary.length>145?'…':''}</p>`:''}<em>${escapeHtml([x.era,(x.people||[]).slice(0,2).join(', ')].filter(Boolean).join(' • '))}</em></div></button>`).join('');list.querySelectorAll('[data-time-id]').forEach(b=>b.onclick=()=>{list.querySelectorAll('.bx-time-item').forEach(x=>x.classList.toggle('active',x===b));timelineDetail(rows.find(x=>x.id===b.dataset.timeId))});if(rows.length===1)list.querySelector('[data-time-id]')?.click()};
 $("#bxTimelineFind")?.addEventListener('click',()=>renderTimeline($("#bxTimelineQuery")?.value));$("#bxTimelineQuery")?.addEventListener('keydown',e=>{if(e.key==='Enter')renderTimeline(e.target.value)});$("#bxTimelineEra")?.addEventListener('change',()=>renderTimeline());document.querySelectorAll('[data-time-type]').forEach(b=>b.onclick=()=>{timelineType=b.dataset.timeType;document.querySelectorAll('[data-time-type]').forEach(x=>x.classList.toggle('active',x===b));renderTimeline()});document.querySelectorAll('[data-bible-section="timeline"]').forEach(btn=>btn.addEventListener('click',()=>setTimeout(()=>renderTimeline(),0)));
 $("#bxTimelineExample")?.addEventListener('click',async()=>{await timelinePutMany([{id:'patriarcas',title:'Era dos Patriarcas',type:'period',era:'patriarchs',startYear:-2000,endYear:-1700,displayDate:'c. 2000–1700 a.C.',approximate:true,testament:'AT',summary:'Período associado às narrativas de Abraão, Isaque, Jacó e José.',people:['Abraão','Isaque','Jacó','José'],places:['Canaã','Harã','Egito'],books:['Gênesis'],refs:['Gênesis 12:1-9','Gênesis 37:1-36']},{id:'exodo',title:'Êxodo do Egito',type:'event',era:'exodus',startYear:-1400,endYear:-1200,displayDate:'data debatida • 2º milênio a.C.',approximate:true,testament:'AT',summary:'Saída de Israel do Egito, travessia, aliança no Sinai e início da peregrinação no deserto. A datação histórica é discutida.',people:['Moisés','Arão','Miriã'],places:['Egito','Sinai','Deserto'],books:['Êxodo','Levítico','Números','Deuteronômio'],refs:['Êxodo 12:31-42','Êxodo 19:1-20']},{id:'davi-rei',title:'Reinado de Davi',type:'king',era:'monarchy',startYear:-1010,endYear:-970,displayDate:'c. 1010–970 a.C.',approximate:true,testament:'AT',summary:'Consolidação da monarquia, Jerusalém como capital e estabelecimento da dinastia davídica.',people:['Davi','Natã','Salomão'],places:['Hebrom','Jerusalém'],books:['1 Samuel','2 Samuel','1 Crônicas'],refs:['2 Samuel 5:1-10','2 Samuel 7:8-17']},{id:'exilio-babilonico',title:'Exílio Babilônico',type:'period',era:'exile',startYear:-586,endYear:-539,displayDate:'586–539 a.C.',approximate:false,testament:'AT',summary:'Período de domínio babilônico após a queda de Jerusalém, seguido pela ascensão persa e retorno de grupos judaítas.',people:['Jeremias','Ezequiel','Daniel','Ciro'],places:['Jerusalém','Babilônia'],books:['Jeremias','Ezequiel','Daniel','Esdras'],refs:['2 Reis 25:1-21','Esdras 1:1-4']},{id:'ministerio-jesus',title:'Ministério público de Jesus',type:'period',era:'jesus',startYear:27,endYear:30,displayDate:'c. 27–30 d.C.',approximate:true,testament:'NT',summary:'Pregação, ensino, sinais, formação dos discípulos, paixão, morte e ressurreição narrados nos Evangelhos.',people:['Jesus','Pedro','João','Tiago'],places:['Galileia','Jerusalém'],books:['Mateus','Marcos','Lucas','João'],refs:['Marcos 1:14-20','Lucas 4:14-21','João 20:1-18']},{id:'paulo-damasco',title:'Conversão e chamado de Paulo',type:'event',era:'church',startYear:34,endYear:36,displayDate:'c. 34–36 d.C.',approximate:true,testament:'NT',summary:'Encontro de Saulo com Cristo no caminho de Damasco e início de uma nova trajetória de testemunho e missão.',people:['Paulo','Ananias'],places:['Damasco'],books:['Atos'],refs:['Atos 9:1-22']},{id:'viagens-paulo',title:'Viagens missionárias de Paulo',type:'journey',era:'church',startYear:46,endYear:57,displayDate:'c. 46–57 d.C.',approximate:true,testament:'NT',summary:'Ciclos missionários narrados em Atos, envolvendo cidades da Ásia Menor, Macedônia e Acaia.',people:['Paulo','Barnabé','Silas','Timóteo','Lucas'],places:['Antioquia','Éfeso','Corinto','Filipos'],books:['Atos'],refs:['Atos 13:1-4','Atos 16:6-15','Atos 18:1-11','Atos 19:1-10']}]);await renderTimeline()});
 $("#bxTimelineNew")?.addEventListener('click',async()=>{const title=prompt('Título do período ou acontecimento:','');if(!title)return;const type=prompt('Tipo: period, event, king, prophet, book, empire ou journey','event');if(type===null)return;const displayDate=prompt('Data exibida (ex.: c. 1000 a.C.):','');if(displayDate===null)return;const summary=prompt('Resumo:','');if(summary===null)return;await timelinePutMany([{title,type,displayDate,summary,approximate:true}]);await renderTimeline()});
 $("#bxTimelineImport")?.addEventListener('click',async()=>{const f=$("#bxTimelineFile")?.files?.[0];if(!f)return alert('Escolha um JSON de cronologia.');try{const j=JSON.parse(await f.text()),rows=Array.isArray(j)?j:(j.timeline||j.chronology||j.cronologia||[]),n=await timelinePutMany(rows);alert(`${n} registro(s) cronológico(s) importado(s).`);await renderTimeline()}catch(e){alert('Falha ao importar linha do tempo: '+e.message)}});$("#bxTimelineExport")?.addEventListener('click',async()=>download('biblia-x-linha-do-tempo.json',JSON.stringify(await timelineAll(),null,2),'application/json'));$("#bxTimelineClear")?.addEventListener('click',async()=>{if(!confirm('Limpar toda a Linha do Tempo local?'))return;await timelineClear();await renderTimeline();const d=$("#bxTimelineDetail");if(d)d.innerHTML='<div class="bx-timeline-detail-empty"><span>🕰️</span><h4>Cronologia limpa</h4></div>'});

 document.querySelectorAll('[data-bible-section="people"]').forEach(btn=>btn.addEventListener('click',()=>setTimeout(()=>renderPeople(),0)));
 let mediaType='all',mediaDetailUrls=[],mediaGridUrls=[],mediaLastRows=[];
 const mediaIcon=t=>({image:'🖼',video:'🎬',audio:'🎧',document:'📄'}[t]||'🎥');
 const bxMediaStorageRefresh=async()=>{const el=$("#bxMediaStorage");if(!el)return;try{if(!navigator.storage?.estimate){el.textContent='Armazenamento local disponível neste navegador.';return}const info=await navigator.storage.estimate(),used=Number(info.usage||0),quota=Number(info.quota||0),fmt=value=>value>=1073741824?`${(value/1073741824).toFixed(1)} GB`:`${(value/1048576).toFixed(1)} MB`;el.textContent=quota?`Uso local: ${fmt(used)} de ${fmt(quota)} disponíveis para o site.`:`Uso local: ${fmt(used)}.`}catch(_){el.textContent='Não foi possível calcular a cota, mas a biblioteca local continua disponível.'}};
 const bxRevokeUrls=list=>{for(const url of list){try{URL.revokeObjectURL(url)}catch(_){}}list.length=0};
 const revokeMediaUrls=(scope='all')=>{if(scope==='all'||scope==='detail')bxRevokeUrls(mediaDetailUrls);if(scope==='all'||scope==='grid')bxRevokeUrls(mediaGridUrls)};
 const mediaUrl=(row,bucket=mediaDetailUrls,thumbnail=false)=>{if(row?.blob){const url=URL.createObjectURL(row.blob);bucket.push(url);return url}return thumbnail?(row?.thumbUrl||row?.sourceUrl||''):(row?.sourceUrl||row?.thumbUrl||'')};
 const bxMediaImageMeta=async file=>{if(!String(file?.type||'').startsWith('image/'))return {width:0,height:0,panorama:false};let width=0,height=0;try{if(window.createImageBitmap){const bitmap=await createImageBitmap(file);width=bitmap.width;height=bitmap.height;bitmap.close?.()}else{const url=URL.createObjectURL(file);try{const image=await new Promise((resolve,reject)=>{const node=new Image();node.onload=()=>resolve(node);node.onerror=reject;node.src=url});width=image.naturalWidth;height=image.naturalHeight}finally{URL.revokeObjectURL(url)}}}catch(_){ }const ratio=width&&height?width/height:0;return {width,height,panorama:width>=1200&&height>=500&&ratio>=1.75&&ratio<=2.25}};
 const bxMediaGalleryRows=(rows,startRow,options={})=>{const urls=[],images=(rows||[]).filter(row=>row.type==='image').map(row=>{let src=row.sourceUrl||row.thumbUrl||'';if(row.blob){src=URL.createObjectURL(row.blob);urls.push(src)}return {...row,sourceUrl:src}}).filter(row=>row.sourceUrl);if(!images.length)return alert('Nenhuma imagem disponível nesta seleção.');const index=Math.max(0,images.findIndex(row=>row.id===startRow?.id)),done=()=>bxRevokeUrls(urls);return bxOpenVisualGallery(images,index,{...options,onClose:done,autoplay:!!options.autoplay})};
 const mediaPreview=row=>{
   const box=$("#bxMediaDetail");if(!box||!row)return;revokeMediaUrls('detail');const url=mediaUrl(row,mediaDetailUrls,false);let player='';
   if(row.type==='image'&&url)player=`<button type="button" class="bx-media-preview-open" data-media-gallery><img class="bx-media-preview-img" src="${escapeHtml(url)}" alt="${escapeHtml(row.title)}">${row.panorama?'<span>🕶️ Abrir panorama 360°</span>':'<span>⛶ Ampliar imagem</span>'}</button>`;
   else if(row.type==='video'&&url)player=`<video class="bx-media-preview-video" src="${escapeHtml(url)}" controls playsinline></video>`;
   else if(row.type==='audio'&&url)player=`<div class="bx-media-audio-wrap"><span>🎧</span><audio src="${escapeHtml(url)}" controls></audio></div>`;
   else player=`<div class="bx-media-file-wrap"><span>${mediaIcon(row.type)}</span><p>${row.blob?'Arquivo armazenado localmente.':row.sourceUrl?'Referência visual pública.':'Registro sem arquivo binário.'}</p>${url?`<a class="btn secondary" href="${escapeHtml(url)}" ${row.blob?`download="${escapeHtml(row.title)}"`:'target="_blank" rel="noopener"'}>Abrir arquivo</a>`:''}</div>`;
   box.innerHTML=`<div class="bx-media-detail-head"><div><span>${mediaIcon(row.type)} ${row.panorama?'PANORAMA 360°':escapeHtml(String(row.type||'mídia').toUpperCase())}</span><h4>${escapeHtml(row.title)}</h4><small>${escapeHtml([row.reference,row.mime,row.width&&row.height?`${row.width}×${row.height}`:'',row.size?Math.round(row.size/1024)+' KB':''].filter(Boolean).join(' • '))}</small></div><button class="btn danger" data-media-delete>Excluir</button></div>${player}${row.description?`<p class="bx-media-description">${escapeHtml(row.description)}</p>`:''}<div class="bx-media-meta"><div><span>Referência</span><b>${escapeHtml(row.reference||'—')}</b></div><div><span>Créditos</span><b>${escapeHtml(row.credits||'—')}</b></div><div><span>Licença</span><b>${escapeHtml(row.license||'—')}</b></div><div><span>Origem</span><b>${row.blob?'Arquivo local':row.sourceKind==='public'?'Referência pública':'Índice local'}</b></div></div>${row.tags?.length?`<section class="bx-media-tags"><span>Palavras-chave</span><div>${row.tags.map(x=>`<i>${escapeHtml(x)}</i>`).join('')}</div></section>`:''}<div class="row bx-media-actions">${row.type==='image'&&url?'<button class="btn secondary" data-media-gallery>🖼️ Galeria</button>':''}${row.panorama&&url?'<button class="btn primary" data-media-pano>🕶️ Ver em 360°</button>':''}${row.reference?`<button class="btn secondary" data-media-open-ref>📖 Passagem</button>`:''}${row.pageUrl?`<a class="btn secondary" href="${escapeHtml(row.pageUrl)}" target="_blank" rel="noopener">Fonte ↗</a>`:''}<button class="btn secondary" data-media-copy>Copiar ficha</button></div>`;
   box.querySelector('[data-media-delete]')?.addEventListener('click',async()=>{if(!confirm(`Excluir "${row.title}" da Mídia X?`))return;await mediaDelete(row.id);box.innerHTML='<div class="bx-media-detail-empty"><span>🎥</span><h4>Item removido</h4><p>Selecione outro item da biblioteca.</p></div>';await renderMedia()});
   box.querySelectorAll('[data-media-gallery]').forEach(button=>button.addEventListener('click',()=>{if(row.panorama)return bxOpenVisualPanorama({...row,sourceUrl:url},{eyebrow:'MÍDIA X • PANORAMA LOCAL'});bxMediaGalleryRows(mediaLastRows,row,{eyebrow:'MÍDIA X • GALERIA DA BIBLIOTECA'})}));
   box.querySelector('[data-media-pano]')?.addEventListener('click',()=>bxOpenVisualPanorama({...row,sourceUrl:url},{eyebrow:'MÍDIA X • PANORAMA 360°'}));
   box.querySelector('[data-media-open-ref]')?.addEventListener('click',async()=>{activate('reader');$("#bRef").value=row.reference;current=await bibleRef(row.reference);$("#bOut").textContent=formatVerses(current)||'Passagem não encontrada na Bíblia local.'});
   box.querySelector('[data-media-copy]')?.addEventListener('click',()=>navigator.clipboard?.writeText([row.title,row.reference,row.description,row.credits,row.license,row.pageUrl,(row.tags||[]).join(', ')].filter(Boolean).join('\n')));
 };
 const renderMedia=async(q='')=>{const grid=$("#bxMediaGrid");if(!grid)return;revokeMediaUrls('grid');let rows=(await mediaAll()).map(normalizeMediaRow);const term=bxV159Norm(q||$("#bxMediaQuery")?.value||'');if(mediaType==='panorama')rows=rows.filter(row=>row.panorama);else if(mediaType!=='all')rows=rows.filter(row=>row.type===mediaType);if(term)rows=rows.filter(row=>bxV159Norm([row.title,row.reference,row.description,row.credits,row.license,row.mime,row.place,...(row.tags||[])].join(' ')).includes(term));rows.sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')));mediaLastRows=rows;const c=$("#bxMediaCount");if(c)c.textContent=`${rows.length} ${rows.length===1?'item':'itens'}${rows.some(row=>row.panorama)?` • ${rows.filter(row=>row.panorama).length} panorama(s)`:''}`;if(!rows.length){grid.innerHTML='<div class="bx-media-empty">Nenhuma mídia encontrada na sua biblioteca.</div>';return}grid.innerHTML=rows.slice(0,300).map(row=>{const url=mediaUrl(row,mediaGridUrls,true),visual=row.type==='image'&&url?`<img loading="lazy" src="${escapeHtml(url)}" alt="${escapeHtml(row.title)}">`:row.type==='video'&&url?`<video src="${escapeHtml(url)}" muted preload="metadata"></video>`:`<span>${mediaIcon(row.type)}</span>`;return `<button class="bx-media-card${row.panorama?' panorama':''}" data-media-id="${escapeHtml(row.id)}"><span class="bx-media-thumb">${visual}${row.panorama?'<i>360°</i>':''}</span><div><strong>${escapeHtml(row.title)}</strong><small>${escapeHtml([row.reference,row.mime,row.blob?'Local':row.sourceKind==='public'?'Pública':'Índice'].filter(Boolean).join(' • ')||'Mídia local')}</small>${row.description?`<p>${escapeHtml(row.description.slice(0,120))}</p>`:''}</div></button>`}).join('');grid.querySelectorAll('[data-media-id]').forEach(button=>button.onclick=()=>{const row=rows.find(item=>item.id===button.dataset.mediaId);grid.querySelectorAll('.bx-media-card').forEach(item=>item.classList.toggle('active',item===button));mediaPreview(row)});if(rows.length===1)grid.querySelector('[data-media-id]')?.click()};
 const bxMediaRenderPublic=async(kind='image')=>{const grid=$("#bxMediaPublicGrid"),query=String($("#bxMediaPublicQuery")?.value||'').trim();if(!grid||!query)return;if(kind==='panorama'&&query&&!/panorama|360/i.test(query)){}grid.innerHTML=`<div class="bx-media-public-empty">${kind==='panorama'?'Procurando imagens panorâmicas 2:1...':'Montando galeria com créditos e licenças...'}</div>`;try{const items=await bxPublicMediaSearch(query,kind,12);grid.__bxItems=items;if(!items.length){grid.innerHTML=`<div class="bx-media-public-empty">${kind==='panorama'?'Nenhum panorama equiretangular foi localizado. Tente outro nome de lugar.':'Nenhuma imagem foi localizada.'}</div>`;return}grid.innerHTML=items.map((item,index)=>`<article class="bx-media-public-card${item.panorama_candidate?' panorama':''}"><button type="button" data-media-public-open="${index}"><img loading="lazy" src="${escapeHtml(item.thumb_url||item.original_url)}" alt="${escapeHtml(item.title||query)}">${item.panorama_candidate?'<i>360°</i>':''}</button><div><strong>${escapeHtml(item.title||query)}</strong><small>${escapeHtml(item.credit||item.artist||item.source||'Wikimedia Commons')}</small><em>${escapeHtml(item.license||'Licença na fonte')}</em></div><nav><button type="button" data-media-public-open="${index}">⛶ Abrir</button>${item.panorama_candidate?`<button type="button" data-media-public-pano="${index}">🕶️ 360°</button>`:''}<button type="button" data-media-public-save="${index}">＋ Salvar no índice</button>${item.page_url?`<a href="${escapeHtml(item.page_url)}" target="_blank" rel="noopener">Fonte ↗</a>`:''}</nav></article>`).join('');grid.querySelectorAll('[data-media-public-open]').forEach(button=>button.onclick=()=>bxOpenVisualGallery(items,Number(button.dataset.mediaPublicOpen),{eyebrow:`MÍDIA X • ${query}`}));grid.querySelectorAll('[data-media-public-pano]').forEach(button=>button.onclick=()=>bxOpenVisualPanorama(items[Number(button.dataset.mediaPublicPano)],{eyebrow:`MÍDIA X • 360° DE ${query}`}));grid.querySelectorAll('[data-media-public-save]').forEach(button=>button.onclick=async()=>{const item=items[Number(button.dataset.mediaPublicSave)];await mediaPutMany([{id:item.id,title:item.title,type:'image',mime:item.mime,description:item.description,tags:[query,'wikimedia-commons',item.panorama_candidate?'360':'imagem'].filter(Boolean),credits:item.credit||item.artist||item.source,license:item.license,licenseUrl:item.license_url,sourceUrl:item.original_url,thumbUrl:item.thumb_url,pageUrl:item.page_url,sourceKind:'public',place:query,width:item.width,height:item.height,panorama:item.panorama_candidate,createdAt:new Date().toISOString()}]);button.textContent='✓ Salvo';button.disabled=true;await renderMedia()})}catch(error){grid.innerHTML=`<div class="bx-media-public-empty">${escapeHtml(error.message||String(error))}<small>Sua biblioteca local continua funcionando offline.</small></div>`}};
