 const bxInstalledChecks=async()=>{
  const translation=selectedTranslation(),testTerm=translation.toLowerCase().startsWith('por')?'amor':'God';
  const specs=[
   ['Bíblia pré-instalada',`/api/bible/status?translation=${encodeURIComponent(translation)}`,data=>data.ready, data=>`${Number(data.verses||0).toLocaleString('pt-BR')} versículos • ${Number(data.books||0)} livros`],
   ['Pesquisa X — Bíblia inteira',`/api/bible/search?q=${encodeURIComponent(testTerm)}&translation=${encodeURIComponent(translation)}&mode=word&scope=all&limit=1`,data=>Array.isArray(data.items),data=>`${Number(data.total||0).toLocaleString('pt-BR')} referências no teste`],
   ['Referências cruzadas / Nave','/api/bible/resources/status',data=>data.ok,data=>`${Number(data.counts?.crossrefs||0).toLocaleString('pt-BR')} ligações • ${Number(data.counts?.nave_topics||0).toLocaleString('pt-BR')} tópicos`],
   ['Strong hebraico e grego','/api/bible/strong/status',data=>data.ready,data=>`${Number(data.lexicon?.total||0).toLocaleString('pt-BR')} verbetes`],
   ['Léxico bíblico','/api/bible/lexicon/status',data=>data.ready,data=>`${Number(data.entries?.total||0).toLocaleString('pt-BR')} análises`],
   ['Contexto histórico e cultural','/api/bible/context/status',data=>data.ready,data=>`${Number(data.profiles||0)} perfis • ${Number(data.articles||0).toLocaleString('pt-BR')} artigos`],
   ['Comentários X','/api/bible/commentary/status',data=>data.ready||Number(data.editorial_guides||0)>0,data=>`${Number(data.editorial_guides||0)} guias • ${Number(data.sections||0)} seções clássicas`]
  ];
  return await Promise.all(specs.map(async([name,url,validate,describe])=>{try{const response=await bxFetch(url),data=await response.json(),ok=!!validate(data);return {name,ok,detail:describe(data)}}catch(error){return {name,ok:false,detail:error.message||'indisponível'}}}));
 };
 const bxDiagRun=async()=>{
  const stores=await bxAllStores(),list=$('#bxDiagList');let total=0,localOk=0;const html=[];
  for(const store of stores){try{const count=(await dbAll(store)).length;total+=count;localOk++;html.push(`<div>✅ <b>${escapeHtml(store)}</b><span>${count.toLocaleString('pt-BR')} registros pessoais</span></div>`)}catch(error){html.push(`<div>⚠️ <b>${escapeHtml(store)}</b><span>${escapeHtml(error.message||'falha de leitura')}</span></div>`)}}
  const installed=await bxInstalledChecks();
  installed.forEach(check=>html.unshift(`<div>${check.ok?'✅':'⚠️'} <b>${escapeHtml(check.name)}</b><span>${escapeHtml(check.detail)}</span></div>`));
  const installedOk=installed.filter(check=>check.ok).length;
  if($('#bxDiagStores'))$('#bxDiagStores').textContent=`${installedOk}/${installed.length}`;
  if($('#bxDiagRows'))$('#bxDiagRows').textContent=total.toLocaleString('pt-BR');
  if($('#bxDiagStatus'))$('#bxDiagStatus').textContent=installedOk===installed.length&&localOk===stores.length?'INTEGRADO':'REVISAR';
  if(list)list.innerHTML=html.join('')||'<div>Nenhum banco encontrado.</div>';
 };
