/* ---------------- acesso às chaves nativas ---------------- */
const bxBM=()=>{try{return JSON.parse(localStorage.getItem("logos-bx:bookmarks")||"[]")}catch(e){return[]}};
const bxHL=()=>{try{return JSON.parse(localStorage.getItem("logos-bx:highlights")||"{}")}catch(e){return{}}};
