/* ---------------- navegação ---------------- */
function openRefStr(ref){
  if(!ref)return false;
  const r=$("#bRef"),o=$("#bOpen");
  if(r){r.value=ref}
  if(o){o.click();return true}
  return false;
}
function navBookChapter(bi,ch){
  const s=$("#bBook");if(!s||bi<0||bi>65)return false;
  s.selectedIndex=bi;
  try{s.dispatchEvent(new Event("change",{bubbles:true}))}catch(e){}
  const cs=$("#bChapter");if(cs){cs.value=String(Math.min(Math.max(1,ch||1),BC[bi]));try{cs.dispatchEvent(new Event("change",{bubbles:true}))}catch(e){}}
  const o=$("#bOpen");if(o){o.click();return true}
  return false;
}

/* ---------------- meta bar do leitor ---------------- */
function mountMeta(){
  const host=$("#bOut");if(!host||!hasVerses())return;
  let m=$(".lmx150-meta",host);
  const bi=curBookIdx(),ch=curCh();
  const bname=bi>=0?BOOK_NAMES[bi]:(currentRef().replace(/\s+\d.*$/,"")||"Bíblia");
  const tot=bi>=0?BC[bi]:0;
  const lin=bi>=0?P[bi]+Math.min(ch,tot)-1:-1;
  const pct=lin>=0?Math.round((lin+1)/TOTAL*100):0;
  if(!m){
    m=document.createElement("div");m.className="lmx150-meta";m.setAttribute("data-lmx150-meta","");
    const top=$(".lmx-bible-v3-top",host);if(top)top.insertAdjacentElement("afterend",m);else host.prepend(m);
  }
  const fav=currentRef()&&bxBM().some(x=>x.ref===currentRef());
  const ttsOn=tts.speaking;
  const _sig=`${bname}|${ch}|${tot}|${pct}|${fav}|${ttsOn}`;
  if(m.dataset.lmx150Sig===_sig)return;
  m.dataset.lmx150Sig=_sig;
  m.innerHTML=
  `<div class="lmx150-meta-row">
    <div class="lmx150-meta-bc"><span>📖</span><b data-lmx150="books" title="Abrir livros">${esc(bname)}</b><span class="sep">›</span><span>Capítulo <b>${ch}</b></span></div>
    <div class="lmx150-meta-count">${tot?`${ch} de ${tot} · `:""}<b>${pct}%</b> da Bíblia</div>
  </div>
  <div class="lmx150-meta-bar"><i style="width:${pct}%"></i></div>
  <div class="lmx150-meta-actions">
    <button data-lmx150="books">📖 Livros</button>
    <button data-lmx150="go">🔍 Ir</button>
    <button data-lmx150="fav" class="${fav?"lmx150-on":""}">${fav?"★ Favorito":"☆ Favoritar"}</button>
    <button data-lmx150="hl">🖍️ Destacar</button>
    <button data-lmx150="tts" class="${ttsOn?"lmx150-on":""}">${ttsOn?"⏹ Parar":"▶️ Ouvir"}</button>
    <button data-lmx150="menu">⚙️ Painéis</button>
  </div>`;
  _lastFavState=fav;
}
let _lastFavState=false;

/* ---------------- footer nav do capítulo ---------------- */
function mountFoot(){
  const host=$("#bOut");if(!host||!hasVerses())return;
  let f=$(".lmx150-foot",host);
  if(!f){f=document.createElement("div");f.className="lmx150-foot";f.setAttribute("data-lmx150-foot","");host.appendChild(f)}
  const tot=curBookIdx()>=0?BC[curBookIdx()]:0;
  const _sig=`${tot}|${curCh()}`;
  if(f.dataset.lmx150FootSig===_sig)return;
  f.dataset.lmx150FootSig=_sig;
  f.innerHTML=
  `<button data-lmx150="prev">← Capítulo anterior</button>
   <button data-lmx150="next">Próximo capítulo →</button>
   <button class="lmx150-foot-aux" data-lmx150="mini">⊕ Ir ao versículo</button>
   <button class="lmx150-foot-aux" data-lmx150="copy">⧉ Copiar capítulo</button>`;
  let mn=$(".lmx150-mini",host);
  if(!mn){mn=document.createElement("div");mn.className="lmx150-mini";mn.setAttribute("data-lmx150-mini","");host.insertBefore(mn,f)}
  mn.innerHTML=`<span>Ir ao versículo</span><input type="number" min="1" max="${tot||200}" value="${curCh()}"><button data-lmx150="mini-go">Ir</button>`;
}

/* ---------------- menu de livros ---------------- */
function bookMenuHTML(filter){
  const q=(filter||"").toLowerCase().trim();
  const parts=[[],[]];
  BOOK_NAMES.forEach((n,i)=>{if(q&&!n.toLowerCase().includes(q))return;const part=i<39?0:1;parts[part].push(`<button class="lmx150-books-item${part?" lmx150-books-nt":""}" data-lmx150-book="${i}" data-name="${esc(n)}"><b>${esc(n)}</b><small>${BC[i]} capítulos · ${part?"NT":"AT"}</small></button>`)});
  return `<section class="lmx150-books-at">${parts[0].join("")||`<div class="lmx150-label">Sem resultado</div>`}</section>
          <section class="lmx150-books-nt-sec">${parts[1].join("")||""}</section>`;
}
function toggleBooks(){
  let b=$("#lmx150-books");
  if(!b){b=document.createElement("div");b.id="lmx150-books";b.className="lmx150-books";document.body.appendChild(b)}
  if(b.classList.contains("open")){b.classList.remove("open");return}
  b.innerHTML=`<div class="lmx150-books-box">
    <div class="lmx150-books-head"><b>📖 Escolha um livro</b><button class="close" data-lmx150="close">✕</button></div>
    <input class="lmx150-books-search" placeholder="Buscar livro…" data-lmx150-search>
    <div class="lmx150-books-grid">${bookMenuHTML("")}</div>
  </div>`;
  b.classList.add("open");
  const inp=b.querySelector("[data-lmx150-search]");
  inp.addEventListener("input",()=>{const grid=b.querySelector(".lmx150-books-grid");grid.innerHTML=bookMenuHTML(inp.value)});
  inp.focus();
}

/* ---------------- TTS ---------------- */
const tts={speaking:false,queue:[],idx:0,rate:1};
function ttsTexts(){return $$("#bOut [data-bx-verse-text]").map(el=>({ref:el.dataset.bxVerseText||"",text:(el.innerText||"").trim()})).filter(x=>x.text)}
function ttsStart(){
  if(!("speechSynthesis" in window)){toast("🔇 TTS não disponível neste navegador");return}
  if(tts.speaking){ttsStop();return}
  const list=ttsTexts();if(!list.length){toast("Nenhum versículo aberto");return}
  tts.speaking=true;tts.queue=list;
  /* 5.4.41 — Ouvir começa no versículo onde está a tarja de leitura. */
  let startIdx=0;
  try{const ctx=window.__bxV157Ctx;if(ctx&&Number.isInteger(ctx.index)&&ctx.index>=0)startIdx=Math.max(0,Math.min(list.length-1,ctx.index));}catch(_){}
  tts.idx=startIdx;ttsSpeakNext();
  toast("▶️ Ouvindo capítulo… (Toque ▶ para parar)",3200);
  const m=$(".lmx150-meta [data-lmx150='tts']");if(m){m.classList.add("lmx150-on");m.textContent="⏹ Parar"}
}
function ttsSpeakNext(){
  if(!tts.speaking)return;
  const item=tts.queue[tts.idx];
  if(!item){ttsStop();return}
  const u=new SpeechSynthesisUtterance(item.text);
  u.lang="pt-BR";u.rate=tts.rate;
  /* 5.4.43 — Voz escolhida (masculina/feminina): vozes do sistema, sem direitos autorais. */
  try{const _vu=ld("ttsVoice","");if(_vu){const _vv=speechSynthesis.getVoices().find(v=>v.voiceURI===_vu);if(_vv)u.voice=_vv;}}catch(e){}
  const el=item.ref?$(`[data-bx-verse-text="${CSS.escape(item.ref)}"]`):null;
  $$(".lmx150-tts-live").forEach(e=>e.classList.remove("lmx150-tts-live"));
  if(el){el.classList.add("lmx150-tts-live");el.scrollIntoView({behavior:"smooth",block:"center"})}
  /* 5.4.40 — Acompanhar a voz no modo foco: a tarja do versículo atual
     (.bx-v157-current) segue a leitura em vez de ficar presa no primeiro. */
  const bxCtx=window.__bxV157Ctx;
  if(bxCtx&&item.ref){const bxIdx=bxCtx.rows.findIndex(r=>r.ref===item.ref);if(bxIdx>=0)bxCtx.setCurrent(bxIdx,false);}
  u.onend=()=>{tts.idx++;setTimeout(ttsSpeakNext,180)};
  u.onerror=()=>{ttsStop(true)};
  try{speechSynthesis.cancel()}catch(e){}
  speechSynthesis.speak(u);
}
function ttsStop(quiet){
  tts.speaking=false;
  try{speechSynthesis.cancel()}catch(e){}
  $$(".lmx150-tts-live").forEach(e=>e.classList.remove("lmx150-tts-live"));
  const m=$(".lmx150-meta [data-lmx150='tts']");if(m){m.classList.remove("lmx150-on");m.textContent="▶️ Ouvir"}
  if(!quiet)toast("⏹ Leitura encerrada");
}
/* 5.4.41 — Expor o leitor de voz ao trilho flutuante (que vive em outro escopo do arquivo). */
window.__bxV157TTS={speaking:()=>tts.speaking,start:ttsStart,stop:ttsStop};

/* ---------------- favoritos (bookmarks nativos) ---------------- */
function favToggle(){
  const ref=currentRef();if(!ref)return toast("Abra um versículo para favoritar");
  let list=bxBM();const i=list.findIndex(x=>x.ref===ref);
  if(i>=0){list.splice(i,1);toast("☆ Removido dos favoritos")}
  else{list.unshift({ref,at:new Date().toISOString()});toast("★ Adicionado aos favoritos")}
  try{localStorage.setItem("logos-bx:bookmarks",JSON.stringify(list.slice(0,120)))}catch(e){}
  const b=$(".lmx150-meta [data-lmx150='fav']");
  if(b){const on=list.some(x=>x.ref===ref);b.classList.toggle("lmx150-on",on);b.textContent=on?"★ Favorito":"☆ Favoritar"}
}

/* ---------------- destaque (highlights nativos) ---------------- */
function hlPop(){
  const ref=currentRef();if(!ref)return toast("Abra um versículo para destacar");
  let p=$("#lmx150-hlpop");
  if(!p){p=document.createElement("div");p.id="lmx150-hlpop";p.className="bx-highlight-menu";document.body.appendChild(p)}
  p.style.left="";p.style.top="";
  const cur=bxHL()[ref]||"";
  p.innerHTML=`<span class="lmx150-label" style="width:100%;display:block">Cor do destaque</span>
    ${["gold","green","blue","rose"].map(c=>`<button data-lmx150-hl="${c}" class="${cur===c?"lmx150-on":""}" style="${cur===c?"border-color:#d6b25e":""}">${c==="gold"?"🟡":c==="green"?"🟢":c==="blue"?"🔵":"🌸"}</button>`).join("")}
    ${cur?`<button data-lmx150-hl="clear">✕ Limpar</button>`:""}`;
  p.classList.add("show");
  const btn=$(".lmx150-meta [data-lmx150='hl']");if(btn){
    const r=btn.getBoundingClientRect();
    p.style.left=Math.max(6,Math.min(innerWidth-p.offsetWidth-6,r.left))+"px";
    p.style.top=(r.bottom+6)+"px";
  }else{p.style.left="50%";p.style.transform="translateX(-50%)";p.style.top="80px"}
}
function hlApply(ref,tone){
  let all=bxHL();
  if(!tone||tone==="clear"){delete all[ref]}
  else{all[ref]=tone}
  try{localStorage.setItem("logos-bx:highlights",JSON.stringify(all))}catch(e){}
  const el=$(`#bOut [data-bx-v3-verse][data-ref="${CSS.escape(ref)}"]`);
  if(el){el.dataset.highlight=tone&&tone!=="clear"?tone:""}
  const pop=$("#lmx150-hlpop");if(pop)pop.remove();
  toast(tone&&tone!=="clear"?`🖍️ Destacado em ${tone}`:"✕ Destaque removido");
}

