      const found=PEOPLE.map(n=>({n,c:(text.match(new RegExp("\\b"+n.toLowerCase()+"\\b","g"))||[]).length})).filter(x=>x.c>0).sort((a,b)=>b.c-a.c).slice(0,10);
      return `<p class="lmx150-label">Personagens que aparecem nesta passagem</p>
        ${found.length?`<div class="lmx150-list">${found.map(({n,c})=>`<button class="lmx150-list-item" data-lmx150-nav="${esc(n)}"><b>${esc(n)}</b><small>mencionado ${c}×</small></button>`).join("")}</div>`:`<div class="lmx150-kpi"><b>—</b><span>Nenhum nome comum detectado nesta passagem</span></div>`}`;
