/* 5.4.44 — Mídias: grid de cartões da busca pública (fetch direto, sem IIFEs) */
function bxVisualNorm(item){
  const x=item||{};
  return {title:x.title||x.name||"Imagem bíblica",src:x.original_url||x.sourceUrl||x.url||x.thumb_url||x.thumbUrl||"",thumb:x.thumb_url||x.thumbUrl||x.original_url||x.sourceUrl||"",pageUrl:x.page_url||x.pageUrl||"",credit:x.credit||x.credits||x.artist||x.source||"",license:x.license||"",description:x.description||""};
}
function bxMediaItemsHtml(){
  if(!bxMedia.items.length)return `<div class="lmx150-kpi"><b>🖼️</b><span>Digite um termo e toque em Buscar — ex.: Jerusalém, arca de Noé, Paulo, Mar da Galileia.</span></div>`;
  return `<div class="lmx150-media-grid">${bxMedia.items.map((item,i)=>{
    const v=bxVisualNorm(item);
    return `<button class="lmx150-media-card" data-lmx150="media-open" data-i="${i}">${v.thumb?`<img src="${esc(v.thumb)}" loading="lazy" alt="${esc(v.title)}">`:`<span class="lmx150-media-ph">${bxMedia.kind==="video"?"🎞️":"🖼️"}</span>`}<b>${esc(v.title.slice(0,64))}</b></button>`;
  }).join("")}</div>`;
}
async function bxRunMedia(){
  const out=$("#lmxMediaOut");if(!out)return;
  if(!bxMedia.q){out.innerHTML=`<div class="lmx150-kpi"><b>?</b><span>Digite um termo para buscar.</span></div>`;return}
  out.innerHTML=`<div class="lmx150-kpi"><b>⏳</b><span>Buscando ${bxMedia.kind==="image"?"imagens":"vídeos"} públicos…</span></div>`;
  try{
    const res=await fetch(`/api/bible/media/public/search?${new URLSearchParams({q:bxMedia.q,kind:bxMedia.kind,limit:"12"})}`,{cache:"no-store"});
    const data=await res.json().catch(()=>({}));
    if(!res.ok)throw new Error(data.detail||"indisponível");
    bxMedia.items=Array.isArray(data.items)?data.items:[];
    out.innerHTML=bxMedia.items.length?bxMediaItemsHtml():`<div class="lmx150-kpi"><b>—</b><span>Nada encontrado para "${esc(bxMedia.q)}".</span></div>`;
  }catch(e){out.innerHTML=`<div class="lmx150-kpi"><b>⚠️</b><span>Fonte visual indisponível no momento. Tente outro termo.</span></div>`}
}
