/* 5.4.133 — barra cinza (.bx-v157-rail) com AUTO-HIDE no celular: some da
   lateral e volta quando a mão passa perto da borda direita (clientX > largura-70).
   Toggla .bx-v157-touch (o CSS 5.4.133 desliza o trilho para dentro/fora). */
(function () {
  if (typeof window.matchMedia !== 'function' || !window.matchMedia('(max-width:760px)').matches) return;
  var timer = null;
  /* 5.4.142 — gatilho apertado: antes aparecia a 70px da borda (dedo
     rolando solta a barra o tempo todo). Agora só num cantinho de ~20px. */
  var isFullNow = function () { return !!document.querySelector('.bible-x-shell.bx-reading-full, .bible-x-shell.bx-page-full'); };
  var near = function (t) {
    if (!t || typeof t.clientX !== 'number') return false;
    if (isFullNow()) return t.clientY > (window.innerHeight - 46); /* tela cheia: dedo na base */
    return t.clientX > window.innerWidth - 20; /* normal: dedo na borda direita */
  };
  var apply = function (on) { var r = document.querySelector('.bx-v157-rail'); if (r) r.classList.toggle('bx-v157-touch', on); };
  var show = function () { apply(true); clearTimeout(timer); timer = setTimeout(function () { apply(false); }, isFullNow() ? 5600 : 3600); }; /* 5.4.173 — tempo DOBRADO: 2.8s→5.6s full, 1.8s→3.6s normal (pedido) */
  var hide = function () { clearTimeout(timer); apply(false); };
  document.addEventListener('touchstart', function (e) { var t = e.touches && e.touches[0]; if (near(t)) show(); }, true);
  document.addEventListener('touchmove', function (e) { var t = e.touches && e.touches[0]; if (near(t)) show(); else hide(); }, { passive: true, capture: true });
  /* mostra o trilho por ~2s ao ENTRAR na tela cheia (para descobrir que ele fica na base) */
  var wasFull = isFullNow();
  setInterval(function () {
    var now = isFullNow();
    if (now === wasFull) return;
    wasFull = now;
    if (now) { apply(true); clearTimeout(timer); timer = setTimeout(function () { apply(false); }, 4400); } /* 5.4.173 — entrar no full revela por 2.2s→4.4s */
    else { apply(false); }
  }, 500);
})();

/* 5.4.134 — botão flutuante "✕ Sair" + Esc para sair da tela cheia.
   O full agora esconde o card lateral e a barra do topo (CSS 5.4.134);
   este botão discreto no canto superior direito é a saída. Aparece só
   quando .bx-*-full está ativo e some ao sair. Observa o <body> inteiro
   (o .bible-x-shell pode não existir no boot) + checagem periódica. */
(function () {
  var BTN = 'lmx134-exit', last = false;
  /* 5.4.164 — no celular este "✕ Sair" do canto superior direito sai de cena:
     o Sair agora fica DENTRO da barra inferior (5.4.164). No PC continua. */
  var isPhone = typeof window.matchMedia === 'function' && window.matchMedia('(max-width:760px)').matches;
  function isFull() {
    return !!document.querySelector('.bible-x-shell.bx-reading-full, .bible-x-shell.bx-page-full');
  }
  function exitFull() {
    if (document.querySelector('.bible-x-shell.bx-reading-full')) {
      if (window.LMXBibleReader) window.LMXBibleReader.full(false);
    } else if (document.querySelector('.bible-x-shell.bx-page-full')) {
      if (window.LMXBXPages) window.LMXBXPages.full(false);
    }
  }
  function sync() {
    if (isPhone) { var hb = document.getElementById(BTN); if (hb) hb.style.display = 'none'; last = false; return; }
    var now = isFull();
    if (now === last) return;
    last = now;
    var b = document.getElementById(BTN);
    if (b) b.style.display = now ? 'flex' : 'none';
  }
  function ensure() {
    if (isPhone) return;
    var b = document.getElementById(BTN);
    if (!b) {
      b = document.createElement('button');
      b.id = BTN;
      b.type = 'button';
      b.textContent = '✕ Sair';
      b.setAttribute('aria-label', 'Sair da tela cheia');
      b.addEventListener('click', function (e) { e.preventDefault(); e.stopPropagation(); exitFull(); });
      document.body.appendChild(b);
    }
    sync();
  }
  if (window.MutationObserver) {
    new MutationObserver(function () { sync(); }).observe(document.body, { subtree: true, attributes: true, attributeFilter: ['class'] });
  }
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && isFull()) { e.preventDefault(); e.stopPropagation(); exitFull(); }
  }, true);
  ensure();
  setInterval(sync, 600);
})();

/* 5.4.164 — FULLSCREEN NATIVO do DOCUMENTO no celular + limpeza por gesto.
   A Bíblia X volta a usar o Fullscreen API NATIVO (pedido do usuário: "volta a
   deixar literalmente em full screen", escondendo a faixa de horas/data). No
   CELULAR o nativo é pedido no <html> (documento inteiro): pedir no shell o
   coloca na top-layer do navegador e ESCONDE a barra inferior (.bx-v157-rail,
   que vive no <body>) e o botão "✕ Sair". Com o <html> em fullscreen o rail e
   o Sair continuam visíveis/clicáveis. Se o gesto do Android (arrastar para
   baixo) encerrar o nativo, o CSS full é desligado aqui. */
(function () {
  if (window.__bxNativeFull) return;
  var phone = function () { return typeof window.matchMedia === 'function' && window.matchMedia('(max-width:760px)').matches; };
  var fsEl = function () { return document.fullscreenElement || document.webkitFullscreenElement; };
  window.__bxNativeFull = {
    phone: phone,
    active: function () { return !!fsEl(); },
    enter: function () {
      if (!phone()) return false;
      if (fsEl()) return true;
      var target = document.documentElement || document.body;
      var req = target.requestFullscreen || target.webkitRequestFullscreen;
      if (!req) return false;
      try { req.call(target, { navigationUI: 'hide' }); return true; } catch (_) { return false; }
    },
    exit: function () {
      var el = fsEl(), ex = document.exitFullscreen || document.webkitExitFullscreen;
      if (el && ex) { try { ex.call(document); } catch (_) {} }
    }
  };
  function cleanupIfOrphan() {
    var shell = document.querySelector('.bible-x-shell');
    if (!shell || fsEl()) return;
    if (shell.classList.contains('bx-reading-full')) {
      if (window.LMXBibleReader) window.LMXBibleReader.full(false);
      else if (window.LMXBX) window.LMXBX.full(false);
    } else if (shell.classList.contains('bx-page-full')) {
      if (window.LMXBXPages) window.LMXBXPages.full(false);
    }
  }
  document.addEventListener('fullscreenchange', function () { if (phone()) cleanupIfOrphan(); });
  document.addEventListener('webkitfullscreenchange', function () { if (phone()) cleanupIfOrphan(); });
})();

(()=>{
  /* 5.4.140 — troca de capítulo no celular começa do versículo 1.
     O swipe e os botões Anterior/Próximo chamam #bPrevChapter/#bNextChapter;
     este listener de CAPTURA roda antes do handler desses botões e seta um
     flag. O #bOpen.onclick (que renderiza o capítulo) consome o flag depois
     e rola o leitor ao topo — só no celular (isMobile). */
  document.addEventListener("click",e=>{
    const t=e.target;
    if(!t||!t.closest)return;
    if(t.closest("#bPrevChapter")||t.closest("#bNextChapter"))window.__bxScrollTopNext=1;
  },true);
})();

/* 5.4.147 — barra cinza no TOPO da tela cheia mobile (.bx-v157-rail horizontal):
   some ao rolar para baixo, reaparece ao rolar para cima (igual lateral na web).
   Toggla .bx-v157-fullhide no <body>; o CSS 5.4.146 anima opacity/transform. */
(function () {
  if (typeof window.matchMedia !== 'function' || !window.matchMedia('(max-width:760px)').matches) return;
  var lastY = 0, ticking = false;
  function isFull() {
    return !!document.querySelector('.bible-x-shell.bx-reading-full, .bible-x-shell.bx-page-full');
  }
  function scroller() {
    /* o proprio shell .bible-x-shell e o container que rola em tela cheia
       (overflow-y:auto; #bOut nao rola sozinho) */
    return document.querySelector('.bible-x-shell.bx-reading-full, .bible-x-shell.bx-page-full') || null;
  }
  function onScroll() {
    ticking = false;
    if (!isFull()) { document.body.classList.remove('bx-v157-fullhide'); lastY = 0; return; }
    var sc = scroller();
    if (!sc) return;
    var y = sc.scrollTop;
    if (y > lastY && y > 4) document.body.classList.add('bx-v157-fullhide');
    else document.body.classList.remove('bx-v157-fullhide');
    lastY = y;
  }
  document.addEventListener('scroll', function () {
    if (!ticking) { ticking = true; requestAnimationFrame(onScroll); }
  }, { passive: true, capture: true });
})();

/* ===== 5.4.148 — PAINEL DE CAIXINHAS: mostrar/ocultar itens do topo =====
   Botao ⚙️ na barra da Biblia (bible-x-toolbar). Abre um painel com tres
   secoes de caixas de selecao:
     1) Barra da Biblia X .... Versao, Livro, Capitulo, Versiculo
     2) Pesquisa biblica ..... Frase, Onde pesquisar, Correspondencia,
        Ordenar, Livros, Pesquisar, Concordancia, Limpar
     3) Linha Rapido ......... "Todos os botoes" (mestre) + cada botao.
   Persiste em logosx:bibleXTopVis. Reaplica a cada re-render
   (MutationObserver) e tambem ao carregar. */
(function(){
  try{
    var KEY="bibleXTopVis";
    var DEFAULTS={
      toolbar:{version:1,book:1,chapter:1,verse:1,open:1,send:1},
      search:{query:1,scope:1,mode:1,sort:1,books:1,find:1,concordance:1,clear:1},
      quick:{all:1,items:{}}
    };
    var QUICK_LABELS={
      "scope-all":"Toda Bíblia","scope-nt":"NT","scope-ot":"AT",
      "larger":"A+","smaller":"A−","reset":"Zoom 100","fullscreen":"⛶ Tela cheia","exit":"✕ Sair (tela cheia)",
      "mode-reading":"📖 Leitura","mode-study":"🔎 Estudo","mode-originals":"🇬🇷 Originais",
      "mode-geography":"🗺️ Geografia","mode-sermon":"🔥 Pregação","mode-all":"🌐 Tudo"
    };
    var cfg=Store.get(KEY,DEFAULTS);
    function norm(c){
      /* default é TUDO VISÍVEL (1). Só vira 0 se o salvo for explicitamente 0. */
      var out={toolbar:{},search:{},quick:{all:1,items:{}}};
      Object.keys(DEFAULTS.toolbar).forEach(function(k){out.toolbar[k]=(c&&c.toolbar&&c.toolbar[k]===0)?0:1});
      Object.keys(DEFAULTS.search).forEach(function(k){out.search[k]=(c&&c.search&&c.search[k]===0)?0:1});
      out.quick.all=(c&&c.quick&&c.quick.all===0)?0:1;
      out.quick.items=(c&&c.quick&&c.quick.items)||{};
      return out;
    }
    cfg=norm(cfg);

    function applyVis(){
      var tb=document.querySelector(".bible-x-toolbar.bx-v158-toolbar");
      if(tb){
        tb.querySelectorAll("[data-bx-vis]").forEach(function(el){
          var on=cfg.toolbar[el.dataset.bxVis]!==0;
          el.classList.toggle("bx-vis-hide",!on);
        });
      }
      var sr=document.querySelector(".bible-x-search-row.bx-v159-search");
      if(sr){
        sr.querySelectorAll("[data-bx-vis]").forEach(function(el){
          if(el.dataset.bxVis==="quick")return;
          var on=cfg.search[el.dataset.bxVis]!==0;
          el.classList.toggle("bx-vis-hide",!on);
        });
      }
      applyQuick();
    }

    /* 5.4.150 — Coleciona os botões de visibilidade da "linha rápida" tanto do
       .bx-v159-quick quanto do .bx-v170-layers (modos Leitura/Estudo/...), que o
       JS pode estar movendo entre containers a cada render (timing). Deduplica. */
    function allQuickButtons(){
      var out=[],seen={};
      document.querySelectorAll(".bx-v159-quick button[data-bx-vis-quick], .bx-v170-layers button[data-bx-vis-quick]").forEach(function(b){
        var k=b.dataset.bxVisQuick;
        if(seen[k])return;seen[k]=1;out.push(b);
      });
      return out;
    }
    function applyQuick(){
      var btns=allQuickButtons();
      var visible=0;
      btns.forEach(function(b){
        var k=b.dataset.bxVisQuick;
        var show=cfg.quick.all?true:(cfg.quick.items[k]===1);
        b.classList.toggle("bx-vis-hide",!show);
        if(show)visible++;
      });
      var quick=document.querySelector(".bx-v159-quick");
      if(quick)quick.classList.toggle("bx-vis-quick-empty",visible===0);
    }

    var panel=null;
    function mkCb(key,label){
      return '<label class="bx-vis-cb"><input type="checkbox" data-bx-vis-cb="'+key+'"> <span>'+label+'</span></label>';
    }
    function buildPanel(){
      if(panel&&!panel.isConnected)panel=null;
      if(panel)return panel;
      var p=document.createElement("div");
      p.className="bx-vis-panel";p.id="bxV158VisPanel";p.hidden=true;
      p.innerHTML=
        '<div class="bx-vis-backdrop" data-bx-vis-close></div>'+
        '<div class="bx-vis-card" role="dialog" aria-modal="true" aria-label="Itens do topo">'+
          '<header>'+
            '<div><small>BÍBLIA X</small><h3>Itens do topo</h3><p>Escolha o que aparece e o que fica oculto. Guardado no seu navegador.</p></div>'+
            '<button type="button" data-bx-vis-close title="Fechar (Esc)">✕</button>'+
          '</header>'+
          '<section>'+
            '<h4>1 · Barra da Bíblia X</h4>'+
            '<div class="bx-vis-grid">'+
              mkCb("toolbar.version","Versão")+mkCb("toolbar.book","Livro")+mkCb("toolbar.chapter","Capítulo")+mkCb("toolbar.verse","Versículo")+
              mkCb("toolbar.open","Abrir")+mkCb("toolbar.send","⚡ Enviar ao Studio")+
            '</div>'+
          '</section>'+
          '<section>'+
            '<h4>2 · Pesquisa bíblica</h4>'+
            '<div class="bx-vis-grid">'+
              mkCb("search.query","🔎 Frase / tema")+mkCb("search.scope","📖 Onde pesquisar")+mkCb("search.mode","“ ” Correspondência")+mkCb("search.sort","↕ Ordenar")+
              mkCb("search.books","☑ Livros")+mkCb("search.find","🔎 Pesquisar")+mkCb("search.concordance","Concordância")+mkCb("search.clear","Limpar")+
            '</div>'+
          '</section>'+
          '<section>'+
            '<h4>3 · Linha Rápido</h4>'+
            '<label class="bx-vis-master"><input type="checkbox" data-bx-vis-cb="quick.all"> <b>Todos os botões</b></label>'+
            '<p class="bx-vis-hint">Desmarque "Todos os botões" para escolher um por um.</p>'+
            '<div class="bx-vis-grid" data-bx-vis-quick-grid></div>'+
          '</section>'+
          '<footer><button type="button" class="btn bx-vis-sair" data-bx-vis-close>Sair</button><button type="button" class="btn primary" data-bx-vis-reset>Restaurar padrão</button></footer>'+
        '</div>';
      document.body.appendChild(p);
      panel=p;
      return p;
    }
    function fillQuickGrid(){
      var p=buildPanel();
      var grid=p.querySelector("[data-bx-vis-quick-grid]");
      if(!grid)return;
      grid.innerHTML="";
      allQuickButtons().forEach(function(b){
          var k=b.dataset.bxVisQuick;
          var label=(b.textContent||"").trim()||QUICK_LABELS[k]||k;
          var el=document.createElement("label");
          el.className="bx-vis-cb";
          el.innerHTML='<input type="checkbox" data-bx-vis-cb="quick.items.'+k+'" data-bx-vis-qk="'+k+'"> <span>'+label+'</span>';
          grid.appendChild(el);
        });
    }
    function syncPanel(){
      var p=buildPanel();
      p.querySelectorAll("[data-bx-vis-cb]").forEach(function(cb){
        var parts=cb.dataset.bxVisCb.split(".");
        var val;
        if(parts[0]==="quick"&&parts[1]==="items"){
          val=cfg.quick.all?true:(cfg.quick.items[parts[2]]===1);
        }else if(parts[0]==="quick"&&parts[1]==="all"){
          val=cfg.quick.all===1;
        }else{
          val=cfg[parts[0]][parts[1]]!==0;
        }
        cb.checked=val;
      });
    }
    function openPanel(){
      var p=buildPanel();
      fillQuickGrid();
      syncPanel();
      p.hidden=false;
    }
    function closePanel(){
      if(panel)panel.hidden=true;
    }

    document.addEventListener("change",function(e){
      var cb=(e.target&&e.target.closest)?e.target.closest("[data-bx-vis-cb]"):null;
      if(!cb)return;
      var parts=cb.dataset.bxVisCb.split(".");
      if(parts[0]==="quick"&&parts[1]==="items"){
        /* se o mestre estava ligado, o usuário está mexendo num item: desliga o
           mestre e pré-preenche os demais como visíveis, para que a marcação/
           desmarcação individual tenha efeito real. */
        if(cfg.quick.all===1){
          cfg.quick.all=0;
          allQuickButtons().forEach(function(b){cfg.quick.items[b.dataset.bxVisQuick]=1});
        }
        if(cb.checked)cfg.quick.items[parts[2]]=1;else delete cfg.quick.items[parts[2]];
      }else if(parts[0]==="quick"&&parts[1]==="all"){
        cfg.quick.all=cb.checked?1:0;
        if(!cb.checked){
          /* desligou o mestre: comeca com todos marcados para nao esvaziar */
          allQuickButtons().forEach(function(b){cfg.quick.items[b.dataset.bxVisQuick]=1});
        }
      }else{
        cfg[parts[0]][parts[1]]=cb.checked?1:0;
      }
      Store.set(KEY,cfg);
      applyVis();
      syncPanel();
    },true);

    document.addEventListener("click",function(e){
      var t=e.target;
      if(t&&t.closest){
        if(t.closest("[data-bx-vis-trigger]")){e.preventDefault();openPanel();return;}
        if(t.closest("[data-bx-vis-close]")){closePanel();return;}
        if(t.closest("[data-bx-vis-reset]")){cfg=norm(null);Store.set(KEY,cfg);applyVis();syncPanel();return;}
      }
    },true);

    document.addEventListener("keydown",function(e){
      if(e.key==="Escape"&&panel&&!panel.hidden)closePanel();
    },true);

    var ticking=false;
    var mo=new MutationObserver(function(){
      if(ticking)return;ticking=true;
      requestAnimationFrame(function(){ticking=false;applyVis();});
    });
    mo.observe(document.body,{childList:true,subtree:true});
    applyVis();
  }catch(err){if(window.console)console.error("bxVis:",err)}
})();



/* ============================================================
   5.4.155 — ☰ "Modos": o 5º botão da barra de baixo do celular
   (antes "Páginas" → Central dos 31 módulos) agora abre um LEQUE
   para CIMA com os modos Leitura/Estudo/Originais/Geografia/Pregação/
   Tudo + ⚙️ Ferramentas do versículo + ⬇️ Bíblia local/offline.
   O painel Central dos 31 módulos segue acessível pelo seletor e
   menuzinho do meio. A barra de modos do topo foi REMOVIDA (pedido).
   Só atua no celular; os toques chamam window.__bxV170Apply.
   ============================================================ */
(function(){
  "use strict";
  var fan=null;
  var MODES=[["reading","📖 Leitura"],["study","🔎 Estudo"],["originals","🇬🇷 Originais"],["geography","🗺️ Geografia"],["sermon","🔥 Pregação"],["all","🌐 Tudo"]];
  function pagesBtn(){
    var nav=document.getElementById("bxMobileBottomNav");
    if(!nav)return null;
    return nav.querySelector('[data-bxm="pages"]');
  }
  function openOffline(){
    try{
      var imp=document.querySelector(".bible-x-import");
      if(imp){imp.setAttribute("open","");try{imp.scrollIntoView({behavior:"smooth",block:"center"})}catch(e1){}return}
    }catch(e){}
    try{
      var m=document.querySelector("#bxOfflineManage");
      if(m){m.click();return}
    }catch(e){}
    try{
      var mo=document.getElementById("bxOfflineModal");
      if(mo&&mo.hidden)mo.hidden=false;
    }catch(e){}
  }
  function modeNow(){
    try{var o=document.querySelector("#bOut");if(o&&o.dataset)return o.dataset.v170Mode||"reading"}catch(e){}
    return "reading";
  }
  function syncActive(){
    if(!fan)return;
    var m=modeNow();
    fan.querySelectorAll("[data-mfan-mode]").forEach(function(b){
      b.classList.toggle("active",b.getAttribute("data-mfan-mode")===m);
    });
  }
  function build(){
    if(fan)return fan;
    fan=document.createElement("div");
    fan.id="bxV170ModeFan";
    fan.setAttribute("role","menu");
    fan.hidden=true;
    MODES.forEach(function(pair){
      var b=document.createElement("button");
      b.type="button";
      b.setAttribute("data-mfan-mode",pair[0]);
      b.title=pair[1];
      b.textContent=pair[1];
      b.addEventListener("click",function(){
        try{window.__bxV170Apply&&window.__bxV170Apply(pair[0])}catch(e){}
        hideFan();
      });
      fan.appendChild(b);
    });
    var g=document.createElement("button");
    g.type="button";
    g.setAttribute("data-mfan-gear","1");
    g.title="Ferramentas do versículo (engrenagem)";
    g.textContent="⚙️ Ferramentas";
    g.addEventListener("click",function(){
      var c=document.querySelector("[data-v170-cfg]");
      if(c){try{c.click()}catch(e){}}
      hideFan();
    });
    fan.appendChild(g);
    var off=document.createElement("button");
    off.type="button";
    off.setAttribute("data-mfan-off","1");
    off.title="Bíblia local / módulos offline";
    off.textContent="⬇️ Offline";
    off.addEventListener("click",openOffline);
    fan.appendChild(off);
    document.body.appendChild(fan);
    return fan;
  }
  function anchor(){
    var b=pagesBtn();if(!b)return;
    var r=b.getBoundingClientRect();
    var right=window.innerWidth-r.right;
    var bottom=window.innerHeight-r.top+8;
    fan.style.right=Math.max(4,Math.round(right))+"px";
    fan.style.bottom=Math.max(4,Math.round(bottom))+"px";
  }
  function showFan(){
    if(!pagesBtn())return;
    build();
    if(!fan)return;
    anchor();
    fan.hidden=false;
    setTimeout(()=>{try{window.bxMaybeTip&&window.bxMaybeTip("modos")}catch(e){}},500);
    syncActive();
    var b=pagesBtn();if(b)b.classList.add("mfan-open");
  }
  function hideFan(){
    if(!fan)return;
    fan.hidden=true;
    var b=pagesBtn();if(b)b.classList.remove("mfan-open");
  }
  function toggleFan(){
    if(!fan||fan.hidden)showFan();else hideFan();
  }
  window.__bxV170ModeFanToggle=toggleFan;
  window.__bxV170ModeFanHide=hideFan;
  document.addEventListener("pointerdown",function(e){
    if(!fan||fan.hidden)return;
    var t=e.target;
    if(t&&t.closest&&(t.closest("#bxV170ModeFan")||t.closest('[data-bxm="pages"]')))return;
    hideFan();
  },true);
  window.addEventListener("scroll",function(){hideFan()},{capture:true,passive:true});
  document.addEventListener("keydown",function(e){if(e.key==="Escape")hideFan()},true);
  window.addEventListener("resize",function(){if(fan&&!fan.hidden)anchor()},{passive:true});
  setInterval(function(){if(fan&&!fan.hidden&&!pagesBtn())hideFan()},600);
})();

/* ============================================================
   5.4.157 — marcador de TELA CHEIA da Bíblia no <body> (.lmx-bx-full).
   Motivo: os efeitos de tela cheia do celular eram todos via
   body:has(.bible-x-shell.bx-reading-full/.bx-page-full). Alguns
   WebViews/navegadores de celular NÃO suportam :has(), então essas
   regras eram ignoradas (topo ficava, engrenagem offline ficava e o
   trilho cinza não virava a barra da base). Este módulo marca o body
   quando QUALQUER full da Bíblia está ativo e remove ao sair; o CSS
   5.4.157 (abaixo no style) usa só esta classe — funciona em qualquer
   navegador, com ou sem :has. ==================================== */
(function () {
  function bibleFull() {
    return !!document.querySelector('.bible-x-shell.bx-reading-full, .bible-x-shell.bx-page-full, #bOut.bx-global-full');
  }
  function sync() {
    var b = document.body; if (!b) return;
    var on = bibleFull();
    if (b.classList.contains('lmx-bx-full') !== on) {
      if (on) b.classList.add('lmx-bx-full'); else b.classList.remove('lmx-bx-full');
    }
  }
  sync();
  if (window.MutationObserver) {
    new MutationObserver(sync).observe(document.body, { subtree: true, attributes: true, attributeFilter: ['class'] });
  }
  setInterval(sync, 500);
})();

/* =============================================================
   5.4.169 — BARRA DE BAIXO da tela cheia da Bíblia
   (a) Fica FIXA embaixo, mas só aparece quando você rola até o FIM
       do texto (some enquanto lê, para não cobrir o versículo; um
       toque/deslize na base também a revela por alguns segundos).
       ANTI-PISCA: a folga do fim (#bOut padding) agora é FIXA via CSS
       e o mostrado/escondido usa histerese (56px mostra / >150px some).
   (b) Botão ⚙️ na barra: catálogo GRANDE de botões (grupos no painel),
       SEM LIMITE de ligados (se passar do tamanho, a barra rola). Os
       extras (data-bx-extra) também podem ser ligados na lateral. ⚙️ e
       ✕ Sair são fixos. Config INDEPENDENTE por contexto: a lateral
       (logosbx:v157railvis) e a barra da tela cheia (logosbx:v157fullvis)
       guardam seleções próprias e não se afetam.
   ============================================================= */
(function () {
  try {
    var MOBILE = typeof window.matchMedia === 'function' && window.matchMedia('(max-width:760px)').matches;

    /* ---------- (a) revelar apenas no fim / toque na base (só full, celular) ---------- */
    var ISET = ['opacity', 'visibility', 'pointerEvents', 'transform'];
    function railEl() { return document.querySelector('.bx-v157-rail'); }
    function setInline(cmd) {
      var r = railEl(); if (!r) return;
      if (cmd === 'clear') { ISET.forEach(function (p) { r.style.removeProperty(p); }); return; }
      ISET.forEach(function (p) { r.style.setProperty(p, cmd[p], 'important'); });
    }
    function showRail() { setInline({ opacity: '1', visibility: 'visible', pointerEvents: 'auto', transform: 'none' }); }
    function hideRail() { setInline({ opacity: '0', visibility: 'hidden', pointerEvents: 'none', transform: 'translateY(120%)' }); }
    function isFull() { return !!document.querySelector('.bible-x-shell.bx-reading-full, .bible-x-shell.bx-page-full'); }
    function atEnd(sc) {
      if (!sc) return false;
      var sh = sc.scrollHeight, ch = sc.clientHeight, st = sc.scrollTop || 0;
      if (sh <= ch + 1) return true;
      return (sh - ch - st) <= 56;
    }
    var tmpUntil = 0;
    var tmpTimer = null;
    var railShown = false;               /* estado atual da barra (histerese) */
    function distEnd(sc) {
      if (!sc) return Infinity;
      var sh = sc.scrollHeight, ch = sc.clientHeight, st = sc.scrollTop || 0;
      if (sh <= ch + 1) return 0;
      return sh - ch - st;
    }
    function compute() {
      var full = isFull();
      if (!full) { setInline('clear'); railShown = false; return; }
      var r = railEl();
      var sc = document.querySelector('.bible-x-shell.bx-reading-full, .bible-x-shell.bx-page-full');
      var d = distEnd(sc);
      var touch = !!r && r.classList.contains('bx-v157-touch');
      var want;
      if (touch || tmpUntil > Date.now()) want = true;   /* toque na base / ao entrar no full */
      else if (d <= 56) want = true;                     /* fim do texto: mostra */
      else if (d > 150) want = false;                    /* longe do fim: esconde */
      else want = railShown;                             /* 56..150: segura o estado atual (anti-pisca) */
      if (want !== railShown) { railShown = want; if (want) showRail(); else hideRail(); }
      /* 5.4.169 — o padding do fim do texto agora é FIXO (CSS), aplicado só quando há
         tela cheia. Antes este compute alternava 90px↔6px inline no #bOut: isso mudava
         o scrollHeight na fronteira do fim e fazia a barra PISCAR a cada frame. */
    }
    var scT = null;
    function onScroll() { if (!scT) { scT = requestAnimationFrame(function () { scT = null; compute(); }); } }
    if (MOBILE) {
      document.addEventListener('scroll', onScroll, { passive: true, capture: true });
      window.addEventListener('resize', onScroll);
      var wasFull = false;
      setInterval(function () {
        var now = isFull();
        if (now !== wasFull) {
          wasFull = now;
          if (now) { tmpUntil = Date.now() + 4400; } else { tmpUntil = 0; } /* 5.4.173 — 2.2s→4.4s ao entrar no full */
        }
        if (now) compute();
      }, 350);
    }

    /* ---------- (b) ⚙️ escolher quais botões aparecem ---------- */
    /* 5.4.171 — catálogo GRANDE (agrupado no painel ⚙️) SEM limite de
       ligados: ligue quantos quiser e a barra rola quando não couber.
       Cada barra guarda a própria seleção (lateral da Bíblia normal
       em logosbx:v157railvis; barra da tela cheia em logosbx:v157fullvis).
       Cada item: [chave, sufixo do data-v157-*, ícone, rótulo, padrão].
       ⚙️ e ✕ Sair são fixos (não entram na lista). */
    var KEYS = { rail: 'logosbx:v157railvis', full: 'logosbx:v157fullvis' };
    var GROUPS = [
      { t: 'Navegação', rows: [
        ['nav','nav','📖','Trocar passagem',1],
        ['chap-prev','chap-prev','⏮','Capítulo anterior',0],
        ['chap-next','chap-next','⏭','Capítulo seguinte',0],
        ['hist-prev','hist-prev','↩','Passagem anterior',0],
        ['hist-next','hist-next','↪','Passagem seguinte',0]
      ]},
      { t: 'Versículo atual', rows: [
        ['listen','listen','🔊','Ouvir capítulo',1],
        ['bookmark','bookmark-current','☆','Marcar versículo',1],
        ['bookmarks','bookmarks','🔖','Lista de marcadores',0],
        ['copy','copy-current','✂','Copiar versículo',1],
        ['share','share','↗','Compartilhar',0],
        ['cite','cite','❞','Citar X',0],
        ['fullscreen','fullscreen','⛶','Tela cheia',1],
        ['more','more','＋','Mais ações',1]
      ]},
      { t: 'Ferramentas de estudo', rows: [
        ['guide','guide','🧭','Guia da passagem',0],
        ['discover','discover','🔭','Descobertas',0],
        ['words','words','🔤','Palavra X',0],
        ['atlas','atlas','🗺','Atlas Instantâneo',0],
        ['context7','context7','7×7','Contexto 7×7',0],
        ['cadeia','cadeia','⛓','Cadeia X',0],
        ['duas','duas','Ⅱ','Duas Passagens',0],
        ['biblioteca','biblioteca','🏛','Biblioteca Pessoal',0],
        ['comparex','comparex','▥','Comparador X',0],
        ['mesa','mesa','▦','Mesa X',0],
        ['network','network','🕸','Rede X',0],
        ['tempo','tempo','🕰','Tempo X',0],
        ['journey','journey','🧭','Jornada X',0],
        ['notebook','notebook','📓','Caderno X',0],
        ['questions','questions','❓','Perguntas X',0],
        ['pulpit','pulpit','🎤','Púlpito',0],
        ['painel360','painel360','◉','Painel 360',0],
        ['central','central','✦','Central X',0],
        ['memoria','memoria','🧠','Memória X',0]
      ]}
    ];
    function allRows() { var a = []; GROUPS.forEach(function (g) { a = a.concat(g.rows); }); return a; }
    function ctxNow() {
      if (document.body && document.body.classList && document.body.classList.contains('lmx-bx-full')) return 'full';
      return document.querySelector('.bible-x-shell.bx-reading-full, .bible-x-shell.bx-page-full') ? 'full' : 'rail';
    }
    function visFor(ctx) {
      var KEY = KEYS[ctx] || KEYS.rail, obj = {};
      try { obj = JSON.parse(localStorage.getItem(KEY) || 'null') || {}; } catch (_) { obj = {}; }
      allRows().forEach(function (m) { if (typeof obj[m[0]] !== 'number') obj[m[0]] = m[4] ? 1 : 0; });
      return obj;
    }
    function saveVisFor(ctx, obj) { try { localStorage.setItem(KEYS[ctx] || KEYS.rail, JSON.stringify(obj)); } catch (_) {} }
    /* migração: quem já tinha a config antiga (chave única, usada na lateral)
       semeia a chave NOVA da tela cheia com a MESMA seleção na primeira vez;
       depois cada uma diverge livremente */
    try {
      if (!localStorage.getItem(KEYS.full)) {
        var _leg = JSON.parse(localStorage.getItem(KEYS.rail) || 'null') || {};
        if (_leg && typeof _leg === 'object') localStorage.setItem(KEYS.full, JSON.stringify(_leg));
      }
    } catch (_) {}
    function countOn(obj) { var n = 0; allRows().forEach(function (m) { if (obj[m[0]]) n++; }); return n; }
    function applyVisFor(ctx) {
      var obj = visFor(ctx);
      var buttons = document.querySelectorAll('.bx-v157-rail button');
      for (var i = 0; i < buttons.length; i++) {
        var b = buttons[i], k = null;
        for (var r = 0; r < allRows().length; r++) { var m = allRows()[r]; if (b.hasAttribute('data-v157-' + m[1])) { k = m[0]; break; } }
        if (k) b.classList.toggle('bx-v157-off', !obj[k]);
      }
    }
    function applyVis() { applyVisFor(ctxNow()); }
    window.__bxV157RailVis = {
      read: function (ctx) { return visFor(ctx || 'rail'); },
      set: function (k, on, ctx) { ctx = ctx || 'rail'; var o = visFor(ctx); o[k] = on ? 1 : 0; saveVisFor(ctx, o); applyVis(); refreshPanel(); }
    };

    var panel = document.createElement('div');
    panel.className = 'bx-v157-settings';
    panel.setAttribute('data-bx-rail-panel', '');
    panel.hidden = true;
    function buildPanelHtml() {
      var h = '<div class="bx-v157-settings-title"><span>Botões da barra<em class="bx-v157-settings-ctx" data-bx-rail-ctx></em></span><b class="bx-v157-settings-count" data-bx-rail-count></b></div>';
      h += '<div class="bx-v157-settings-body">';
      GROUPS.forEach(function (g) {
        h += '<div class="bx-v157-settings-group"><div class="bx-v157-settings-group-t">' + g.t + '</div>';
        g.rows.forEach(function (m) {
          h += '<label class="bx-v157-settings-row"><span class="bx-v157-settings-ico">' + m[2] + '</span><span class="bx-v157-settings-lb">' + m[3] + '</span><input type="checkbox" data-bx-rail-k="' + m[0] + '"></label>';
        });
        h += '</div>';
      });
      h += '</div>';
      h += '<div class="bx-v157-settings-hint">Sem limite: ligue quantos quiser e a barra rola. ⚙️ e ✕ Sair ficam sempre. A edição vale só para a barra indicada no topo (lateral ou tela cheia).</div>';
      return h;
    }
    panel.innerHTML = buildPanelHtml();
    document.body.appendChild(panel);
    var countEl = panel.querySelector('[data-bx-rail-count]');
    var ctxEl = panel.querySelector('[data-bx-rail-ctx]');
    function refreshLimitUI() {
      var on = countOn(visFor(ctxNow()));
      if (countEl) countEl.textContent = on + ' ligados';
    }
    function refreshPanel() {
      var ctx = ctxNow();
      var obj = visFor(ctx);
      panel.querySelectorAll('[data-bx-rail-k]').forEach(function (cb) { cb.checked = !!obj[cb.dataset.bxRailK]; });
      if (ctxEl) ctxEl.textContent = (ctx === 'full' ? '· tela cheia' : '· lateral');
      refreshLimitUI();
    }
    function openPanel() {
      refreshPanel();
      panel.hidden = false;
      panel.style.left = '';
      panel.style.top = '';
      panel.style.bottom = '';
      var pw = Math.min(320, Math.max(200, innerWidth - 16));
      var g = document.querySelector('[data-v157-settings]');
      var full = isFull();
      if (g && !full) {
        var r = g.getBoundingClientRect();
        var ph = panel.offsetHeight || 320;
        var top = r.top - ph - 8;
        if (top < 8) top = Math.min(r.bottom + 8, Math.max(8, innerHeight - ph - 8));
        panel.style.left = Math.max(8, Math.min(innerWidth - pw - 8, r.left)) + 'px';
        panel.style.top = top + 'px';
        panel.style.bottom = 'auto';
      } else {
        panel.style.left = Math.max(8, Math.round((innerWidth - pw) / 2)) + 'px';
        panel.style.top = 'auto';
        panel.style.bottom = full ? 'calc(118px + env(safe-area-inset-bottom,0px))' : (MOBILE ? '84px' : '30px');
      }
      var body = panel.querySelector('.bx-v157-settings-body');
      if (body) body.scrollTop = 0;
    }
    function closePanel() { panel.hidden = true; }
    document.addEventListener('click', function (e) {
      var t = e.target;
      if (!t || !t.closest) return;
      var gear = t.closest('[data-v157-settings]');
      if (gear) { e.preventDefault(); e.stopPropagation(); if (panel.hidden) openPanel(); else closePanel(); return; }
      if (!panel.hidden && !t.closest('[data-bx-rail-panel]')) closePanel();
    }, true);
    document.addEventListener('change', function (e) {
      var cb = e.target && e.target.closest && e.target.closest('[data-bx-rail-k]');
      if (!cb) return;
      var ctx = ctxNow();
      var obj = visFor(ctx);
      obj[cb.dataset.bxRailK] = cb.checked ? 1 : 0;
      saveVisFor(ctx, obj);
      applyVisFor(ctx);
      refreshPanel();
    }, true);

    var deb = null;
    function scheduleVis() { if (deb) return; deb = requestAnimationFrame(function () { deb = null; applyVis(); }); }
    if (window.MutationObserver) {
      new MutationObserver(scheduleVis).observe(document.body, { childList: true, subtree: true });
      try { new MutationObserver(scheduleVis).observe(document.body, { attributes: true, attributeFilter: ['class'], subtree: true }); } catch (_) {}
    }
    applyVis();
  } catch (_) {}
})();

/* =============================================================
   5.4.169 — TROCA DE CAPÍTULO sem "apagar" o texto:
   mini-pill "Carregando capítulo…" (sem limpar o versículo atual e
   sem a sombra/brilho de fora a fora do overscroll). A pill some
   sozinha quando o novo capítulo renderiza ou em caso de erro.
   ============================================================= */
(function () {
  try {
    var el = null;
    function ensure() {
      if (el && el.isConnected) return el;
      el = document.createElement('div');
      el.className = 'bx-chapter-loading';
      el.setAttribute('role', 'status');
      el.hidden = true;
      document.body.appendChild(el);
      return el;
    }
    window.__bxChapterLoading = {
      show: function (ref) {
        var e = ensure();
        var r = String(ref || '').trim();
        e.textContent = '⏳ Carregando ' + (r ? 'capítulo ' + r : 'passagem') + '…';
        e.hidden = false;
      },
      hide: function () { if (el && el.isConnected) el.hidden = true; }
    };
  } catch (_) {}
})();

/* =============================================================
   5.4.169 — DOIS TOQUES rápidos sobre o texto da Bíblia:
   entra na tela cheia; dois toques de novo, sai da tela cheia.
   Só em aparelhos de toque e só sobre o texto dos versículos
   (não atrapalha botões, inputs nem o duplo-clique do desktop).
   ============================================================= */
(function () {
  try {
    if (!('ontouchstart' in window)) return;
    var lastT = 0, lastX = 0, lastY = 0;
    function isFull() { return !!document.querySelector('.bible-x-shell.bx-reading-full, .bible-x-shell.bx-page-full'); }
    function exitFull() {
      var rd = document.querySelector('.bible-x-shell.bx-reading-full');
      var pg = document.querySelector('.bible-x-shell.bx-page-full');
      if (rd) { if (window.LMXBibleReader) window.LMXBibleReader.full(false); else if (window.LMXBX) window.LMXBX.full(false); }
      else if (pg && window.LMXBXPages && window.LMXBXPages.full) window.LMXBXPages.full(false);
      else if (window.__bxNativeFull) window.__bxNativeFull.exit();
    }
    function enterFull() {
      if (window.LMXBibleReader && document.querySelector('.bible-x-shell')) window.LMXBibleReader.full(true);
      else if (window.LMXBXPages && window.LMXBXPages.full && document.querySelector('.bible-x-shell')) window.LMXBXPages.full(true);
      else if (window.__bxNativeFull) window.__bxNativeFull.enter();
    }
    function insideVerse(t) {
      if (!t || !t.closest) return false;
      if (!t.closest('#bOut .lmx-bible-v3-list, .bible-x-shell .lmx-bible-v3-list')) return false;
      if (t.closest('button, a, input, select, textarea, [data-v155-select], .bx-v157-rail')) return false;
      return true;
    }
    document.addEventListener('touchend', function (e) {
      var t = e.target;
      if (!insideVerse(t)) { lastT = 0; return; }
      var ch = e.changedTouches && e.changedTouches[0];
      if (!ch) return;
      var now = Date.now();
      if (lastT && (now - lastT) <= 300 && Math.abs(ch.clientX - lastX) <= 28 && Math.abs(ch.clientY - lastY) <= 28) {
        lastT = 0;
        if (e.cancelable) e.preventDefault();
        if (isFull()) exitFull(); else enterFull();
        return;
      }
      lastT = now; lastX = ch.clientX; lastY = ch.clientY;
    }, { passive: false });
  } catch (_) {}
})();

/* ============================================================
   5.4.172 — DICAS CONTEXTUAIS POR ÁREA (mobile + web)
   Cada área/lugar onde o usuário entra pode ter uma caixinha curta
   de "Comandos rápidos": 1 ícone + dicas reais. Toda caixa tem ✕,
   "Entendi" e a opção "Não mostrar novamente" (persistida por área).
   - uma única instância por vez (não empilha)
   - cada área aparece 1× por sessão até ser dispensada para sempre
   - persistência em localStorage via Store (prefixo logosx:)
   ============================================================ */
(function(){
  const R=(ico,txt)=>`<li><span class="bxq-ico">${ico}</span><span>${txt}</span></li>`;
  const TIPS={
    bible:{mark:"📖",eyebrow:"BÍBLIA X",title:"Comandos rápidos",rows:ph=>ph?[
        R("👈👉","Deslize o dedo: <b>esquerda</b> = próximo capítulo &nbsp;•&nbsp; <b>direita</b> = capítulo anterior"),
        R("⚡","Dois <b>toques rápidos</b> no texto entram na <b>tela cheia</b>; dois toques rápidos voltam à leitura."),
        R("🕹️","Na barra de baixo: <b>🏠 Home</b>, <b>▦ Módulos</b>, <b>☰ Painéis</b>, <b>📥 Importar</b> e <b>🎛️ Modos</b>."),
        R("🛠️","Na <b>borda direita</b> há uma <b>aba dourada fina</b>: passe o dedo perto dela (ou toque nela) para abrir as <b>ferramentas de leitura</b>.")
      ]:[
        R("⌨️","Atalhos: <b>N</b> próximo capítulo &nbsp;•&nbsp; <b>P</b> capítulo anterior &nbsp;•&nbsp; <b>F</b> foco de leitura"),
        R("📖","Toque em um <b>versículo</b> para abrir as ferramentas (Referências, Strong, Léxico, Comentários…)."),
        R("🕹️","A barra do topo troca de módulo; <b>☰ Painéis</b> abre os painéis de estudo e tutoriais.")
      ]},
    full:{mark:"⛶",eyebrow:"BÍBLIA X",title:"Tela cheia",rows:ph=>ph?[
        R("⚡","Dois <b>toques rápidos</b> no texto <b>saem</b> da tela cheia e voltam à leitura."),
        R("⚙️","Toque <b>⚙️</b> para escolher quais botões aparecem na barra; o último, <b>✕ Sair</b>, volta à leitura."),
        R("👈👉","Deslize para o lado também troca de capítulo aqui na tela cheia.")
      ]:[
        R("⌨️","Pressione <b>Esc</b> (ou <b>✕ Sair</b> na barra) para voltar à leitura."),
        R("🕹️","Os botões da barra agem sobre o versículo atual; <b>⚙️</b> escolhe quais aparecem.")
      ]},
    modos:{mark:"🎛️",eyebrow:"BÍBLIA X",title:"Modos",rows:ph=>ph?[
        R("📖","Escolha o <b>módulo</b>: 📖 Leitura, 🔎 Estudo, 🇬🇷 Originais, 🗺️ Geografia, 🔥 Pregação ou 🌐 Tudo."),
        R("⚙️","O <b>⚙️ Ferramentas</b> abre o leque do que aparece abaixo do versículo."),
        R("⬇️","O <b>⬇️ Offline</b> abre a Bíblia local / importação de traduções.")
      ]:[
        R("🎛️","A faixa do topo alterna os módulos; <b>🌐 Tudo</b> reúne todos abaixo da leitura.")
      ]},
    modulos:{mark:"▦",eyebrow:"BÍBLIA X",title:"Todos os módulos",rows:()=>[
        R("▦","Cada quadrado é um <b>ambiente</b> da Bíblia X. Toque para abrir."),
        R("📌","O módulo em uso fica destacado na grade."),
        R("✕","Feche pelo <b>✕</b> no alto ou tocando fora do painel.")
      ]},
    paineis:{mark:"☰",eyebrow:"BÍBLIA X",title:"Painéis & Ferramentas",rows:()=>[
        R("🌀","Atalhos de leitura: <b>Foco</b>, <b>Mergulho</b>, <b>Largura</b>, <b>Brilho</b>…"),
        R("📑","Abaixo, os <b>painéis</b> de estudo: Favoritos, Notas, Concordância, Strong, Léxico e mais."),
        R("❓","Cada painel com <b>?</b> ou <b>▶</b> tem um mini tutorial narrado 🔊.")
      ]},
    import:{mark:"📥",eyebrow:"BÍBLIA X",title:"Importar Bíblia",rows:ph=>ph?[
        R("📄","Escolha um arquivo (<b>JSON/CSV/TXT</b>) de uma tradução cuja licença permita o uso."),
        R("🔒","O texto fica <b>neste navegador</b> — nada é enviado à internet."),
        R("✕","Feche pelo <b>✕</b> no alto ou tocando de novo em <b>📥 Importar</b>.")
      ]:[
        R("📄","Escolha um arquivo (<b>JSON/CSV/TXT</b>) de uma tradução cuja licença permita o uso."),
        R("🔒","O texto fica <b>neste navegador</b> — nada é enviado à internet."),
        R("🧪","Use <b>Status</b> para conferir o que já está carregado.")
      ]}
  };
  const isPhone=()=>{try{return window.matchMedia("(max-width:760px)").matches}catch(_){return false}};
  function bxTipDismissed(area){try{if(Store.get("tip:"+area)==="1")return true;if(area==="bible"&&Store.get("logosx:bxQuickGuideNever")==="1")return true}catch(_){}return false}
  function bxTipClose(wrap){
    try{const cb=wrap&&wrap.querySelector(".bxq-never input");if(cb&&cb.checked)Store.set("tip:"+wrap.__area,"1")}catch(_){}
    window.__bxTipOpen=null;if(wrap&&wrap.remove)wrap.remove();
  }
  function bxTipShow(area){
    try{
      if(!TIPS[area])return;
      if(window.__bxTipShown&&window.__bxTipShown[area])return;
      if(bxTipDismissed(area))return;
      if(window.__bxTipOpen)return;
      document.querySelectorAll(".bx-guide-overlay").forEach(function(n){try{n.remove()}catch(_){}});
      const c=TIPS[area],ph=isPhone();
      const wrap=document.createElement("div");
      wrap.className="bx-guide-overlay bx-guide-area";
      wrap.setAttribute("role","dialog");wrap.setAttribute("aria-modal","true");
      wrap.innerHTML='<div class="bx-guide-card"><header><span class="bxq-mark">'+c.mark+'</span><div><small>'+c.eyebrow+'</small><h3>'+c.title+'</h3></div><button type="button" class="bxq-close" aria-label="Fechar">✕</button></header><ul>'+c.rows(ph).join("")+'</ul><footer><label class="bxq-never"><input type="checkbox">Não mostrar novamente</label><button type="button" class="bxq-ok">Entendi</button></footer></div>';
      wrap.__area=area;
      window.__bxTipOpen=area;
      if(!window.__bxTipShown)window.__bxTipShown={};
      window.__bxTipShown[area]=true;
      const ok=wrap.querySelector(".bxq-ok"),cl=wrap.querySelector(".bxq-close");
      if(ok)ok.addEventListener("click",function(){bxTipClose(wrap)});
      if(cl)cl.addEventListener("click",function(){bxTipClose(wrap)});
      wrap.addEventListener("click",function(e){if(e.target===wrap)bxTipClose(wrap)});
      const host=document.fullscreenElement||document.querySelector(".bible-x-shell.bx-reading-full,.bible-x-shell.bx-page-full")||document.body;
      (host||document.body).appendChild(wrap);
    }catch(e){}
  }
  window.bxMaybeTip=bxTipShow;
  /* fecha a janelinha de importar pelo ✕ injetado no <details> */
  document.addEventListener("click",function(e){
    const t=e.target&&e.target.closest?e.target.closest(".bx-import-x"):null;
    if(!t)return;
    e.preventDefault();
    const d=t.closest("details.bible-x-import");if(d)d.open=false;
  });
  /* observa a entrada na tela cheia para mostrar a dica (uma única vez) */
  let bxFullWatch=null;
  function bxStartFullWatch(){
    if(bxFullWatch)return;
    let seen=false;
    const check=function(){try{const f=document.querySelector(".bible-x-shell.bx-reading-full,.bible-x-shell.bx-page-full");if(f&&!seen){seen=true;setTimeout(function(){seen=false;bxTipShow("full")},420)}else if(!f){seen=false}}catch(_){}};
    try{bxFullWatch=new MutationObserver(check);bxFullWatch.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:["class"]})}catch(_){}
    setTimeout(check,900);
  }
  window.__bxTipEnsureWatchers=bxStartFullWatch;
})();

/* ============================================================
   5.4.173b — ABA discreta (#bx-v157-grip) do trilho auto-hide
   .bx-v157-rail, SEM o balão de dica (retirado a pedido).
   A dica dessa barra agora mora no card "Comandos rápidos" da
   área 'bible' (motor 5.4.172) — o que aparece ao iniciar a
   Bíblia. Tempos dobrados já aplicados no JS 5.4.133/5.4.169:
   1.8s→3.6s normal, 2.8s→5.6s full, 2.2s→4.4s ao entrar no full.
   A aba indica onde a barra escondida está: tocar nela abre a
   barra (mesmo sinal .bx-v157-touch do 5.4.133); some na tela
   cheia (lá a barra vira a base) e se apaga quando a barra abre.
   ============================================================ */
(function () {
  try {
    if (window.__bxV157UX) return;                 /* já instalado */
    var FULL = '.bible-x-shell.bx-reading-full,.bible-x-shell.bx-page-full';
    function rail() { return document.querySelector('.bx-v157-rail'); }
    function isFull() { return !!document.querySelector(FULL); }
    var GRIP = null, openTimer = null;

    function openRail() {
      if (isFull()) return;                        /* no full a aba não existe */
      var r = rail();
      if (!r) return;
      r.classList.add('bx-v157-touch');            /* mesmo sinal do 5.4.133 */
      clearTimeout(openTimer);
      openTimer = setTimeout(function () { r.classList.remove('bx-v157-touch'); }, 3600);
    }

    function sync() {
      if (!GRIP) return;
      var full = isFull();
      /* aba acesa: leitura normal com barra FECHADA. Apagada: barra aberta,
         sem trilho, ou tela cheia (ali o CSS também a esconde por completo). */
      var lit = !!rail() && !full && !document.querySelector('.bx-v157-rail.bx-v157-touch');
      GRIP.classList.toggle('bx-v173-dim', !lit);
    }

    function init() {
      if (window.__bxV157UX) return;
      if (!document.body) { document.addEventListener('DOMContentLoaded', init); return; }
      if (document.getElementById('bx-v157-grip')) { window.__bxV157UX = { open: openRail }; return; }
      GRIP = document.createElement('button');
      GRIP.id = 'bx-v157-grip';
      GRIP.type = 'button';
      GRIP.setAttribute('aria-label', 'Abrir ferramentas de leitura');
      GRIP.addEventListener('pointerdown', function (e) { e.preventDefault(); openRail(); });
      document.body.appendChild(GRIP);
      setInterval(sync, 250);
      window.__bxV157UX = { open: openRail };
    }
    init();
  } catch (e) { /* nunca derruba o app */ }
})();
